(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c4"]=[{"id":"00002606","register_sub_id":"101","register_pk":"103596","name":"旧陸軍演習場内圍壁","kana":"きゅうりくぐんえんしゅうじょうないいへき","category":"その他","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県習志野市東習志野4-15-6","lat":35.69500587,"lng":140.0752884,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造、延長20m、鉄筋コンクリート造2階建付","structure_material":"鉄筋コンクリート造","registered":"2002.02.14(平成14.02.14)","register_no":"12 － 0041","desc":"長２０ｍ，高３．３ｍ，厚３０ｃｍほどの鉄筋コンクリート造壁と３ｍ角平面の２階建望楼部から成る。壁体部には２段に銃眼が穿たれ，東寄りにアーチ状の入口を開ける。入口上部の扁額状銘板から年代と工兵第一大隊による築造が知られる。演習場遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002606"},{"id":"00000758","register_sub_id":"101","register_pk":"101748","name":"千葉工業大学通用門（旧鉄道第二連隊表門）","kana":"ちばこうぎょうだいがくつうようもん（きゅうてつどうだいにれんたいおもてもん）","category":"その他","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県習志野市津田沼2-17-1","lat":35.68966359,"lng":140.02188532,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造門柱４基からなる，幅10.6m","structure_material":"煉瓦造門柱４基からなる","registered":"1998.09.02(平成10.09.02)","register_no":"12 － 0007","desc":"明治４３年移駐の陸軍鉄道連隊第三大隊（大正７年鉄道第二連隊に改組）の表門。鉄道連隊関係施設で現存する数少ないもののひとつで，煉瓦造の４本の門柱が残る。土地の歴史を知る上で貴重な建造物で，現在は「工大の煉瓦門」の愛称で広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000758"},{"id":"00002370","register_sub_id":"101","register_pk":"103360","name":"寛永寺渋沢家霊堂","kana":"かんえいじしぶさわけれいどう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都台東区上野桜木1-14-11","lat":35.721706,"lng":139.774979,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"13 － 0112","desc":"渋沢栄一前妻の１７回忌にあわせて建設と伝える。桁行４間半，梁行４間半，宝形造，瓦葺で，正面は両開桟唐戸，その左右に花頭窓が付き，柱上に舟形肘木を載せる。軒は一軒疎垂木。内部の内陣境の欄間彫刻，杉板小壁や杉戸等の彩色画に見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002370"},{"id":"00012881","register_sub_id":"101","register_pk":"367989","name":"旧九段会館","kana":"きゅうくだんかいかん","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都千代田区九段南一丁目5-1","lat":35.69437778,"lng":139.75139167,"geo_status":"db","era":"昭和9年／昭和32年・同58年・平成30年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造4階地下1階建、瓦葺、建築面積1620㎡","structure_material":"鉄骨鉄筋コンクリート造4階地下1階建","registered":"2019.09.10(令和1.09.10)","register_no":"13 － 421","desc":"内堀通りに建つ鉄骨鉄筋コンクリート造4階建の複合施設。軍人会館として競技設計1等案をもとに建てられた。通り沿いは両端に城郭風の入母屋造塔屋を戴く歴史主義の和風表現を基調に、要所にアール・デコの手法を取り入れる。九段下の街路景観の象徴的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012881"},{"id":"00000951","register_sub_id":"101","register_pk":"101941","name":"東京水産大学雲鷹丸","kana":"とうきょうすいさんだいがくうんようまる","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都港区港南4-5-7","lat":35.62512542,"lng":139.74919461,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"鋼製帆船，長さ41.2m，最大幅8.7m","structure_material":"鋼製帆船","registered":"1998.12.11(平成10.12.11)","register_no":"13 － 0042","desc":"東京水産大学の前身である農商務省水産講習所の練習船として大阪鉄工所桜島工場で建造された。３本マストのバーク型「鋼製補助機関付」帆船で，国産鋼製船舶としては現存最古のものになる。昭和３７年，大学のシンボルとして喫水線上部が現位置に移設された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000951"},{"id":"00008668","register_sub_id":"101","register_pk":"149389","name":"弥彦公園トンネル","kana":"やひここうえんとんねる","category":"その他","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦字御殿山667-1他","lat":37.69970212,"lng":138.82796037,"geo_status":"db","era":"大正7年／昭和62年改修","year":1918,"year_source":"converted","year_min":1918,"year_max":1918,"year_label":null,"structure":"煉瓦造、延長55m、幅員3.1m","structure_material":"煉瓦造","registered":"2011.07.25(平成23.07.25)","register_no":"15 － 0341","desc":"園内中央西側に位置する小山に設けられる。馬蹄形アーチ断面になる煉瓦造の歩行者用トンネルで、延長55ｍを測る。坑門はアーチ周縁や壁柱、笠石を花崗岩で造り、壁面を煉瓦で化粧する。造営時の気風を伝える象徴的な公園施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008668"},{"id":"00011280","register_sub_id":"101","register_pk":"209116","name":"石川県立美術館広坂別館（旧陸軍第九師団長官舎）","kana":"いしかわけんりつびじゅつかんひろさかべっかん（きゅうりくぐんだいきゅうしだんちょうかんしゃ）","category":"その他","subcategory":"建築物","type_guess":"官舎・住宅","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市出羽町1","lat":36.560873,"lng":136.660743,"geo_status":"db","era":"大正11／昭和中期・同63・平成27改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積248㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"17－0257","desc":"兼六園南方に建つもと師団長官舎の洋館部。正面はハーフティンバー調とし、車寄を張り出す。半切妻の大屋根を架け、平側に切妻破風を突出させて特徴とする。内部では応接室や旧食堂の暖炉飾などに当初の意匠を残す。大正期軍官舎の通例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011280"},{"id":"00000405","register_sub_id":"101","register_pk":"101395","name":"旧陸軍金沢偕行社","kana":"きゅうりくぐんかなざわかいこうしゃ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県金沢市出羽町7他","lat":36.55919167,"lng":136.66164444,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造2階建，瓦葺，建築面積282㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"17 － 0006","desc":"マンサ－ド風の屋根を持つ中央棟の左右に，寄棟の翼屋が付く構造になる。コリント式のピラスターやドーマー窓等バロック風の技巧的な装飾を用いた外観意匠は，全体として華やかで優れている。明治４２年に現在地に移築したと伝える。設計は，陸軍経理部。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000405"},{"id":"00000404","register_sub_id":"101","register_pk":"101394","name":"旧陸軍第九師団司令部庁舎","kana":"きゅうりくぐんだいきゅうしだんしれいぶちょうしゃ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県金沢市出羽町7他","lat":36.55894167,"lng":136.66181667,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造2階建，瓦葺，建築面積275㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"17 － 0005","desc":"左右対称型の構成になり，正面のペディメントやピラスタ－，上下窓など簡素なルネサンス風の外観を見せる。明治期の庁舎建築の好例。旧金沢城内に建築されたが，昭和４５年に現在地に移築され，その際両翼の一部が切り縮められた。設計は，陸軍経理部。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000404"},{"id":"00003960","register_sub_id":"101","register_pk":"104950","name":"中村神社拝殿（旧金沢城二の丸能舞台）","kana":"なかむらじんじゃはいでん（きゅうかなざわじょうにのまるのうぶたい）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県金沢市中村町16-1","lat":36.561203,"lng":136.644455,"geo_status":"db","era":"江戸末期／明治3・昭和40移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0090","desc":"金沢城二の丸能舞台を移築改造。方３間，４隅角柱上三斗組，二軒疎垂木，入母屋造，桟瓦葺で，正側面に刎高欄付切目縁を回し，外回りを双折桟唐戸，格子戸引違で仕切り内部は折上格天井とする。内法上の派手な蟇股や丸彫嵌め彫刻に往時の豪奢な姿をとどめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003960"},{"id":"00005756","register_sub_id":"101","register_pk":"106744","name":"山梨大学赤レンガ館","kana":"やまなしだいがくあかれんがかん","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲府市北新1-4-2","lat":35.67871333,"lng":138.56776556,"geo_status":"db","era":"明治41頃","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積330㎡","structure_material":"煉瓦造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"19 － 0055","desc":"歩兵４９連隊糧秣庫として建設。煉瓦造平屋建，切妻造，桟瓦葺で，桁行２０間，梁間５間規模。当初は桁行を４等分して間仕切り，各室の両側面と両妻面に櫛形アーチの戸口を設け，櫛形アーチの窓を開く。外壁は煉瓦のオランダ積。小屋組はキングポストトラス。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005756"},{"id":"00009276","register_sub_id":"101","register_pk":"194069","name":"旧松本歩兵第五十連隊糧秣庫（信州大学医学部資料室）","kana":"きゅうまつもとほへいだいごじゅうれんたいりょうまつこ（しんしゅうだいがくいがくぶしりょうしつ）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県松本市旭3-696-1","lat":36.25115478,"lng":137.98017906,"geo_status":"db","era":"明治41年頃","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積330㎡","structure_material":"煉瓦造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"20 － 0423","desc":"信州大学の敷地内に建ち、桁行三六・三メートル梁間九・一メートル、煉瓦造平屋建、切妻造桟瓦葺である。外壁はイギリス積で北面三箇所、西面一箇所の戸口を設け、欠円アーチ窓を開く。小屋組はキングポストトラスとする。校地の歴史を伝える煉瓦倉庫である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009276"},{"id":"00011133","register_sub_id":"101","register_pk":"205240","name":"西駒山荘石室","kana":"にしこまさんそういしむろ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県伊那市伊那7119-140","lat":35.806064,"lng":137.829458,"geo_status":"db","era":"大正4／大正15・昭和24・平成26改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"石造平屋建、鋼板葺、建築面積42㎡","structure_material":"石造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"20 - 0500","desc":"中央アルプス木曽駒ヶ岳の北東方、標高約二七〇〇メートルの稜線上に南北棟で建つ。大振りの花崗岩割石を布積した躯体に、キングポストトラスの小屋を組む。強風の吹く西側は軒下まで土砂で埋め、東側に小窓を穿つ。近代登山における石室式の山小屋の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011133"},{"id":"00002393","register_sub_id":"101","register_pk":"103383","name":"山田旅館薬師堂","kana":"やまだりょかんやくしどう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県北安曇郡小谷村大字中土18836","lat":36.8622483,"lng":137.98068413,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"20 － 0098","desc":"新館の東北方，浴室の北方の山際に南面して建つ。南北棟，入母屋造，もと茅葺，妻入で，方１間半程度の規模を有する。簡素な薬師堂であるが，病の療養にきた湯治客にとって祈願の施設が不可欠であったことを物語る建造物として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002393"},{"id":"00004965","register_sub_id":"101","register_pk":"105955","name":"岐阜公園三重塔","kana":"ぎふこうえんさんじゅうのとう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県岐阜市槻谷13-2","lat":35.434681,"lng":136.77582626,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造三重塔、瓦葺、建築面積24㎡","structure_material":"木造三重塔","registered":"2005.11.10(平成17.11.10)","register_no":"21 － 0058","desc":"石造二重基壇上に建つ木造三重塔。各層とも方三間で，円柱を立てて尾垂木付の三手先組物を配し，上層には刎高欄を廻す。軒は二軒繁垂木で，本瓦葺屋根を架ける。装飾を用いない古風な意匠で，設計は伊東忠太。金華山の西麓にあって広く市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004965"},{"id":"00005602","register_sub_id":"101","register_pk":"106590","name":"震災紀念堂","kana":"しんさいきねんどう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市若宮町2-10","lat":35.4203,"lng":136.762024,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0089","desc":"市街地にあり，ほぼ南面して建つ。入母屋造，桟瓦葺，正面唐破風造の向拝付で，平面は外陣，内陣及び余間の構成になり，側廻りは角柱に舟肘木を載せる。震災紀念堂としては我が国最初のもので，外観，内部とも浄土真宗本堂形式を基調としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005602"},{"id":"00002627","register_sub_id":"101","register_pk":"103617","name":"凱旋紀念門","kana":"がいせんきねんもん","category":"その他","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町渋川","lat":34.92408914,"lng":137.68615525,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"煉瓦造、幅3.2m、高さ3.6m","structure_material":"煉瓦造","registered":"2002.02.14(平成14.02.14)","register_no":"22 － 0079","desc":"日露戦争を記念して，神社参道の途中に築かれた。石造柱脚の上に，柱頭を鋸歯飾とした煉瓦造柱が立ち上がり，煉瓦造欠円アーチを挟み込む。大型の扁額を嵌め込んだフランス積壁面の上部に，江戸切仕上石材の重厚な笠石を載せる。県内初期の煉瓦造構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002627"},{"id":"00000435","register_sub_id":"101","register_pk":"101425","name":"愛知大学旧本館（旧陸軍第15師団司令部庁舎）","kana":"あいちだいがくきゅうほんかん（きゅうくりぐんだいじゅうごしだんしれいぶちょうしゃ）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県豊橋市町畑町1-1","lat":34.74009563,"lng":137.38648544,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建，瓦葺，建築面積1859㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"23 － 0009","desc":"木造２階建で，両翼屋を背後に突き出したコの字形平面をもつ。外壁に下見板を貼り，装飾をあまり用いない簡素なつくりで，縦長の上下窓を均等に配置するなど標準化の傾向がみられる。明治末期の陸軍による兵営建築の手法をよく示す建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000435"},{"id":"00005764","register_sub_id":"101","register_pk":"106752","name":"オリエンタルビル屋上観覧車","kana":"おりえんたるびるおくじょうかんらんしゃ","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"愛知県","address":"愛知県名古屋市中区栄3-5-1","lat":35.1685171,"lng":136.90593656,"geo_status":"db","era":"昭和31","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"鉄骨造、高さ12m、脚間6.2m","structure_material":"鉄骨造","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0233","desc":"デパートの屋上に設置。二基の三角錐状鉄骨架構の支柱間に直径１０ｍの鉄骨製円形ホイールを取り付け，ホイール外周部に鉄骨製の４人乗ケージ９個を吊り下げる。娯楽遊戯施設の専門業者である東京の昭和鉄工株式会社が納入している。現存最古級の観覧車遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005764"},{"id":"00000214","register_sub_id":"101","register_pk":"101204","name":"乃木倉庫","kana":"のぎそうこ","category":"その他","subcategory":"建築物","type_guess":"倉庫・蔵","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市中区本丸1","lat":35.18618301,"lng":136.89748382,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"煉瓦造平屋建，瓦葺，建築面積91㎡","structure_material":"煉瓦造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"23 － 0005","desc":"乃木将軍が命じ５年頃に名古屋に赴任したことにちなんで名付けられたと伝える名古屋城御深井丸に位置する旧陸軍の火薬庫。煉瓦造、平屋建で、屋根を切妻造、桟瓦葺とする。角を石積み風に造り出す等の高度な技術に見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000214"},{"id":"00003860","register_sub_id":"101","register_pk":"104850","name":"明治村歩兵第六聯隊兵舎","kana":"めいじむらほへいだいろくれんたいへいしゃ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.343311,"lng":136.99086,"geo_status":"db","era":"明治6／昭和40移築","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造2階建、瓦葺、建築面積389㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0094","desc":"木造２階建，寄棟造。当初は桁行５０ｍを超える建物で，移築時に３分の２に縮めた。外壁は白漆喰塗の大壁に胴蛇腹を巡らせ，やや幅広の上げ下げ窓を開く。入口はポーチの起り屋根をトスカナ式円柱が支え，櫛形欄間付の唐戸を開く。鎮台時代兵舎建築の遺存例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003860"},{"id":"00003888","register_sub_id":"101","register_pk":"104878","name":"旧北伊勢陸軍飛行場掩体","kana":"きゅうきたいせりくぐんひこうじょうえんたい","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県鈴鹿市三畑町5079-72","lat":34.90800299,"lng":136.49674467,"geo_status":"db","era":"昭和18頃","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"鉄筋コンクリート造、建築面積533㎡","structure_material":"鉄筋コンクリート造","registered":"2004.02.17(平成16.02.17)","register_no":"24 － 0049","desc":"旧北伊勢飛行場と近隣の航空機用施設とを結ぶ誘導路沿いに位置する。 鉄筋コンクリート造で，平面は正面幅２９．６ｍ奥行８．４ｍの長方形部分と，奥行１４．７ｍ最小幅９．１ｍの台形部分からなる。第二次世界大戦末期における中型規模の掩体の一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003888"},{"id":"00002656","register_sub_id":"101","register_pk":"103646","name":"千里寺本堂","kana":"せんりじほんどう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府吹田市千里山西1-37-42","lat":34.777363,"lng":135.505066,"geo_status":"db","era":"昭和3／昭和7移築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積502㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"27 － 0177","desc":"昭和天皇即位大礼の饗宴場の一部を転用したもの。桁行約３０ｍ，梁間約１７ｍ，入母屋造，本瓦葺，妻入で，東正面に４間の向拝を付す。移築・転用で改造も多いが，角柱を長押で固めた軸部，内部の二重折上格天井，照明器具等，近代宮殿建築の姿を良く留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002656"},{"id":"00002971","register_sub_id":"101","register_pk":"103961","name":"多木浜洋館記念碑","kana":"たきはまようかんきねんひ","category":"その他","subcategory":"その他工作物","type_guess":"記念碑・像","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県加古川市別府町東町174","lat":34.72264363,"lng":134.84606792,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"石造、面積148㎡","structure_material":"石造","registered":"2002.08.21(平成14.08.21)","register_no":"28 － 0109","desc":"主屋西北方に位置する。我国人造肥料製造の鼻祖で多木製肥所の創始者である多木久米次郎（1859～1942）の銅像所として建設。北木島産花崗石による簡潔かつ豪放な造形を有し，底面１４尺四方高１８尺の台石には時の総理大臣斎藤実の書による「肥料主」を刻む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002971"},{"id":"00003129","register_sub_id":"101","register_pk":"104119","name":"姫路市立美術館（旧第十師団兵器庫）","kana":"ひめじしりつびじゅつかん（きゅうだいじゅうしだんへいきこ）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県姫路市本町68-25","lat":34.839703,"lng":134.696564,"geo_status":"db","era":"明治38頃／大正2増築","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積2923㎡","structure_material":"煉瓦造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"28 － 0115","desc":"兵器庫として建てられた煉瓦造建築。南北棟の増築部分の設計は棟札より陸軍技手宮本平治，井田熊吉があたったことが知られる。一時期市庁舎として使用され，後に美術館となった。姫路城の一角にあって，姫路市の近代の歩みを示す建物として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003129"},{"id":"00013618","register_sub_id":"101","register_pk":"504895","name":"旧加太砲台厠","kana":"きゅうかだほうだいかわや","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県和歌山市加太1907-2","lat":34.27045833,"lng":135.06746389,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"30 － 0288","desc":"弾廠の南に建つ切妻造の桟瓦葺である。南北両妻に階段を設けて中廊下とし、東側に仕切りなしで溝が連なる小便所、西側に八室の大便所である。小便所側は煉瓦積基礎を腰高まで積む。外壁は簓子下見板張で東西両面に無双窓を開く。類例少なく貴重な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013618"},{"id":"00013617","register_sub_id":"101","register_pk":"504894","name":"旧加太砲台弾廠","kana":"きゅうかだほうだいだんしょう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県和歌山市加太1907-2","lat":34.27071111,"lng":135.06730833,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"30 － 0287","desc":"大阪湾防衛のため紀淡海峡を望む山上に築かれた砲台の弾薬庫である。切妻造桟瓦葺の南北棟で三室に間仕切り、中央室は弾架を設けた作業場、北室と南室は詰所とみられる。キングポストトラスまで鉋仕上とした上質な造りを持つ。要塞の実相を伝えて貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013617"},{"id":"00000413","register_sub_id":"101","register_pk":"101403","name":"祇園閣","kana":"ぎおんかく","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市東山区四条通大和大路東入祇園町南側594-1","lat":35.00214625,"lng":135.7797585,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造・鉄骨鉄筋コンクリート造3階建，銅板葺，建築面積67㎡","structure_material":"鉄筋コンクリート造・鉄骨鉄筋コンクリート造3階建","registered":"1997.12.12(平成9.12.12)","register_no":"26 － 0010","desc":"大倉喜八郎の依頼により，伊東忠太が設計した普請道楽の一つ。施工大倉土木。総高約３４ｍの３階建塔状建築で，下層及び基礎部分を鉄筋コンクリート造，中層以上を鉄骨鉄筋コンクリートとする。山鉾をかたどった和風の外観，内部のグロテスク型の照明は特異。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000413"},{"id":"00010984","register_sub_id":"101","register_pk":"208954","name":"聖母女学院法人本館","kana":"せいぼじょがくいんほうじんほんかん","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市伏見区深草田谷町1","lat":34.958592,"lng":135.772376,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"煉瓦造2階建、銅板葺、建築面積879㎡","structure_material":"煉瓦造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"26-0499","desc":"もと陸軍第一六師団の司令部庁舎。長さ六〇メートルに及ぶ煉瓦造二階建で、正面中央はイオニア式の大オーダーとペディメントで威厳をもたせ、両翼はトスカナ式意匠とし、屋根に大小のドーマー窓を並べる。内部の階段なども上質。師団司令部庁舎の希少例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010984"},{"id":"00000159","register_sub_id":"101","register_pk":"101149","name":"島根県立浜田高等学校第二体育館（旧歩兵第21連隊雨覆練兵場）","kana":"しまねけんりつはまだこうとうがっこうだいにたいいくかん（きゅうほへいだいにじゅういちれんたいあめおおいれんぺいじょう）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"島根県","address":"島根県浜田市黒川町3749","lat":34.89908549,"lng":132.09675002,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造平屋建，スレート葺，建築面積644㎡","structure_material":"煉瓦造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"32 － 0008","desc":"浜田市立第一中学校屋内運動場と同じく，旧陸軍の屋内練兵場の建物を再利用したもの。建築の年代は大正５年と新しいが，構造規模ともほぼ同様になる。県道の際にあり同窓生はもとより道行く人にも広く知られた建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000159"},{"id":"00000158","register_sub_id":"101","register_pk":"101148","name":"浜田市立第一中学校屋内運動場（旧歩兵第21連隊雨覆練兵場）","kana":"はまだしりつだいいちちゅうがっこうおくないうんどうじょう（きゅうほへいだいにじゅういちれんたいあめおおいれんぺいじょう）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県浜田市黒川町3745","lat":34.90166841,"lng":132.09731103,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"煉瓦造平屋建，スレート葺，建築面積639㎡","structure_material":"煉瓦造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"32 － 0007","desc":"煉瓦造，切妻造，波形鉄板葺，棟に明かり取りを兼ねた小屋根をかける。質素な外観ながら，小屋組にＬ型鋼のフィンクトラスを用いて室内空間を造り出す点は壮観である。山陰地方で煉瓦造及び鉄骨小屋組を用いた建造物の最初期の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000158"},{"id":"00009375","register_sub_id":"101","register_pk":"194168","name":"岡山県総合グラウンドクラブ（旧岡山偕行社）","kana":"おかやまけんそうごうぐらうんどくらぶ（きゅうおかやまかいこうしゃ）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区いずみ町1-1","lat":34.67766925,"lng":133.91861439,"geo_status":"db","era":"明治43年／昭和25年改修・昭和43年・平成15年移築改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積324㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"33 － 0252","desc":"総合グラウンド南東部に東面して建つ。木造二階建、寄棟造桟瓦葺、桁行二三･七メートル梁間一〇・九メートル、正面左右に切妻の階段室を張出す。外観は半円ペディメントやイオニア式円柱を用いた古典様式で整える。現代的な運動公園に歴史的な彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009375"},{"id":"00006037","register_sub_id":"101","register_pk":"107022","name":"岡山大学情報展示室（旧陸軍第十七師団司令部衛兵所）","kana":"おかやまだいがくじょうほうてんじしつ（きゅうりくぐんだいじゅうななしだんしれいぶえいへいじょ）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区津島中1-1-1","lat":34.68668569,"lng":133.919479,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"33 － 0150","desc":"市街地北方に位置する岡山大学津島キャンパスの正門脇に建つ。桁行７．３ｍ，梁間５．５ｍ規模の寄棟造，平屋建で，平側に上下窓を配す。外壁はドイツ下見板張，腰縦板張とし，基礎は煉瓦積とする。小規模ながら丁寧なつくりで，正門廻りの景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006037"},{"id":"00004179","register_sub_id":"101","register_pk":"105169","name":"野﨑武左衛門翁旌徳碑","kana":"のざきぶざえもんおうしょうとくひ","category":"その他","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野2-2129-2","lat":34.47202102,"lng":133.80331988,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"石造、高さ18m、台座面積66㎡","structure_material":"石造","registered":"2004.06.09(平成16.06.09)","register_no":"33 － 0086","desc":"オベリスク型の記念碑。コンクリート基礎上に，約８ｍ四方の基壇を花崗岩で組み，その上方に上下２組の台座，さらに長１２ｍ一本石の尖角柱を立ち上げ全体高１８ｍとする。我国で珍しいエジプト趣味の建造物。設計はフランス帰りの土木技師山田寅吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004179"},{"id":"00004182","register_sub_id":"101","register_pk":"105172","name":"野﨑武左衛門翁旌徳碑石垣","kana":"のざきぶざえもんおうしょうとくひいしがき","category":"その他","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野2-2129-2","lat":34.46864242,"lng":133.80056877,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"石造、延長128m","structure_material":"石造","registered":"2004.06.09(平成16.06.09)","register_no":"33 － 0089","desc":"敷地の東面及び北面を囲む高さ１．１ｍ，折れ曲がり延長１２８ｍの石垣。台形縦断面を有する小型の石材を敷地正面の両端と中央部に計４基配する。敷地正面・側面の隅部を亀甲積，それ以外の部分を谷積とするなど，外観に変化をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004182"},{"id":"00004180","register_sub_id":"101","register_pk":"105170","name":"野﨑武左衛門翁旌徳碑石橋","kana":"のざきぶざえもんおうしょうとくひいしばし","category":"その他","subcategory":"土木構造物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野2-2129-2","lat":34.47184246,"lng":133.80330402,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"石造桁橋、橋長4.4m、幅員2.0m","structure_material":"石造桁橋","registered":"2004.06.09(平成16.06.09)","register_no":"33 － 0087","desc":"旌徳碑の手前に位置し，敷地内の池に架けられた太鼓橋風の石造桁橋。表面ビシャン叩仕上の花崗岩を用い，橋長４．４ｍ，幅員２．０ｍとし，頂部を四角錐とした親柱を四隅に配する。縦断線形の湾曲を低く押さえ，旌徳碑へのパースペクティブ効果を高めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004180"},{"id":"00004181","register_sub_id":"101","register_pk":"105171","name":"野﨑武左衛門翁旌徳碑門柱","kana":"のざきぶざえもんおうしょうとくひもんちゅう","category":"その他","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野2-2129-2","lat":34.47176254,"lng":133.80340854,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"石造、高さ4.7m","structure_material":"石造","registered":"2004.06.09(平成16.06.09)","register_no":"33 － 0088","desc":"旌徳碑の敷地の入口に配される。面取と浅彫が施された直方体の上部に，葉をかたどった凹状軒蛇腹風の装飾，さらには笠石，丸みを帯びた錘形の飾りを載せ，高さ４．７ｍとする。手の込んだ丁寧な造りで，オベリスクの意匠を意識した造形を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004181"},{"id":"00013337","register_sub_id":"101","register_pk":"366326","name":"旧江田島海軍下士卒集会所（海友舎）二階建棟","kana":"きゅうえたじまかいぐんかしそつしゅうかいしょ（かいゆうしゃ）にかいだてとう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県江田島市江田島町中央二丁目17490","lat":34.24765833,"lng":132.47676667,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造二階建、瓦葺、建築面積83㎡","structure_material":"木造二階建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0279","desc":"旧海軍下士卒の集会場の正面棟。木造二階建、寄棟造桟瓦葺で、正面中央部に切妻造の玄関ポーチをを張出し、二階にバルコニーを設ける。下見板張の外壁に上下窓を並べ、玄関ポーチの欄間や持送に意匠を凝らす。現存する希少な木造の下士卒集会所であり貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013337"},{"id":"00013338","register_sub_id":"101","register_pk":"366327","name":"旧江田島海軍下士卒集会所（海友舎）平屋建棟","kana":"きゅうえたじまかいぐんかしそつしゅうかいしょ（かいゆうしゃ）ひらやだてとう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県江田島市江田島町中央二丁目17490","lat":34.24763889,"lng":132.47698333,"geo_status":"db","era":"明治38年／昭和3年移築","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積192㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0280","desc":"二階建棟の東背面に建つ。明治38年に建てた旧呉海軍下士卒集会所桜松館を昭和３年に移築したもの。木造平屋建、寄棟造桟瓦葺で、平面はＬ字型で武道場と遊技室で構成する。二階建棟とともに木造の旧海軍下士卒集会所として希少な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013338"},{"id":"00009065","register_sub_id":"101","register_pk":"162425","name":"呉市入船山記念館旧高烏砲台火薬庫","kana":"くれしいりふねやまきねんかんきゅうたかからすほうだいかやくこ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県呉市幸町1-1","lat":34.2398757,"lng":132.56470241,"geo_status":"db","era":"明治35年／昭和42年移築","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積41㎡","structure_material":"石造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"34 － 0124","desc":"南北棟の切妻造桟瓦葺。桁行９．７ｍ梁間４．２ｍ、瘤出し仕上げの花崗岩を積み上げ、西面中央に欠円アーチの出入口を開ける。東・西面に二所、南・北面中央に一所の矩形窓を穿つ。妻床下には欠円アーチを設け、換気に配慮する。重厚な倉庫の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009065"},{"id":"00000903","register_sub_id":"101","register_pk":"101893","name":"呉市水道局二河水源地取入口","kana":"くれしすいどうきょくにこうすいげんちとりいれぐち","category":"その他","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県呉市大字荘山田村字東二河平甲1653-1","lat":34.26766462,"lng":132.55761862,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"石造，延長11.8m","structure_material":"石造","registered":"1998.10.09(平成10.10.09)","register_no":"34 － 0020","desc":"呉鎮守府の軍用水道施設のひとつ。宮原浄水場に導水するために二河峡にある水源地につくられた石造の坑門で，上部に「呉鎮守府水道」と刻まれた標石を置く。アーチ形の開口部両脇に柱型をあらわした丁寧なつくりで，我が国初期の水道施設のひとつとして貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000903"},{"id":"00000901","register_sub_id":"101","register_pk":"101891","name":"呉市水道局宮原浄水場低区配水池","kana":"くれしすいどうきょくみやはらじょうすいじょうていくはいすいち","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県呉市青山町5-2","lat":34.2373444,"lng":132.56693984,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"煉瓦造，幅37m，長さ44.4m","structure_material":"煉瓦造","registered":"1998.10.09(平成10.10.09)","register_no":"34 － 0018","desc":"呉鎮守府の軍用水道は，横浜，函館に続き我が国で３番目にできた水道施設で，宮原浄水場はそのひとつとしてつくられた。配水池の容量は 8,000立米で，煉瓦造の上屋を設ける。簡素ながら我が国初期の水道施設の様子を知る上で貴重な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000901"},{"id":"00016435","register_sub_id":"101","register_pk":"536502","name":"呉ＹＷＣＡ会館","kana":"くれわいだぶりゅしーえーかいかん","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県呉市幸町2-1","lat":34.24157778,"lng":132.56584722,"geo_status":"db","era":"昭和前期／昭和53年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、鉄板葺、建築面積294㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"34 - 0324","desc":"呉港東の高台に建つＹＷＣＡの会館。敷地に合わせたＶ字平面で２階建切妻造鉄板葺、外壁下見板張。隅切部に縦長窓を開けて吹抜ホールとし、踊場付階段で二階へ上る。二階床の合成梁など特徴的な構法を用い、角地に建つ洋風の外観が地域のランドマーク的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016435"},{"id":"00003311","register_sub_id":"101","register_pk":"104301","name":"飛弾家住宅観音堂","kana":"ひだけじゅうたくかんのんどう","category":"その他","subcategory":"建築物","type_guess":"官舎・住宅","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県呉市豊町大長5368","lat":34.18090208,"lng":132.85452165,"geo_status":"db","era":"明治初期／大正末期移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"34 － 0041","desc":"蔵門南側に並んで建つ。道路側の東を正面とした小規模な仏堂で，平面は１辺３ｍで，正面に庇柱を立て，本瓦葺屋根は宝形造とし，正面に庇を葺き降ろす。外壁が真壁造と簡素であるが，屋敷側床下を当家の墓所とするなど，当地の信仰形態が伺える数少ない事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003311"},{"id":"00007403","register_sub_id":"101","register_pk":"108385","name":"周南市市長公舎洋館","kana":"しゅうなんししちょうこうしゃようかん","category":"その他","subcategory":"建築物","type_guess":"官舎・住宅","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県周南市慶万町1821-2","lat":34.050526,"lng":131.814148,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"35 － 0062","desc":"細長い敷地の後方に位置する。急勾配の切妻屋根の妻壁を西正面に見せ、その北に南北棟の切妻屋根を２段に設ける。腰に煉瓦、その上に黄土色の化粧タイルを貼り、上部はハーフティンバー風とする。内部は玄関と応接間等からなる。穏やかな外観になる洋館の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007403"},{"id":"00007404","register_sub_id":"101","register_pk":"108386","name":"周南市市長公舎和館","kana":"しゅうなんししちょうこうしゃわかん","category":"その他","subcategory":"建築物","type_guess":"官舎・住宅","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県周南市慶万町1821-2","lat":34.050461,"lng":131.814331,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積238㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"35 － 0063","desc":"洋館の東に接して建つ。東西棟の寄棟造を主棟に、落棟の切妻屋根や寄棟屋根、両下屋根を出し、変化に富む屋根構成を見せる。トコや棚、平書院を構える十畳の座敷や次の間を西側に設け、東には中廊下で、浴室や台所ほか私的な居室を配する。良質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007404"},{"id":"00004424","register_sub_id":"101","register_pk":"105414","name":"安藝家バラッケ（旧板東俘虜収容所）","kana":"あきけばらっけ（きゅうばんどうふりょしゅうようじょ）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県鳴門市大麻町桧字椎尾谷37","lat":34.16816157,"lng":134.49256573,"geo_status":"db","era":"大正6／昭和43移築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積199㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"36 － 0048","desc":"桁行１５間梁間４間，木造平屋建，切妻造，桟瓦葺である。現在は改造され農業用倉庫となっているが，当初は桁行４０間の規模を有し，内部は中央の土間通路を挟み，左右に低い板床を張って２間毎に間仕切られていた。簡素な建物であるが，軍関係営舎の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004424"},{"id":"00004425","register_sub_id":"101","register_pk":"105415","name":"柿本家バラッケ（旧板東俘虜収容所）","kana":"かきもとけばらっけ（きゅうばんどうふりょしゅうようじょ）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県鳴門市大麻町桧字東山田53","lat":34.16386667,"lng":134.49884167,"geo_status":"db","era":"大正6／昭和43移築／平成18移築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積198㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"36 － 0049","desc":"桁行１５間梁間４間，木造平屋建，切妻造，スレート葺である。当初は桁行４０間の規模を有し，内部は中央の土間通路を挟み，左右に低い板床を張って２間毎に間仕切られていた。簡素な建物であるが，軍関係営舎の一例。平成18年に道の駅「第九の里」公園内に移築されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004425"},{"id":"00002686","register_sub_id":"101","register_pk":"103676","name":"旧陸軍第一一師団兵舎棟","kana":"きゅうりくぐんだいじゅういちしだんへいしゃとう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県善通寺市文京町3-2-1","lat":34.226288,"lng":133.781784,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積878㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"37 － 0084","desc":"四国学院大学キャンパスの西北方に位置し２号館校舎として使用。桁行５８．５ｍ，梁行１５ｍ規模，桟瓦葺，寄棟造の木造２階建兵舎で，南面中央に１本石によるロマネスク風大オーダーと大振りなペディメントにより類例のない玄関ポーチを造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002686"},{"id":"00016742","register_sub_id":"101","register_pk":"579226","name":"明治天皇丸亀行在所址碑","kana":"めいじてんのうまるがめあんざいしょあとひ","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県丸亀市大手町二丁目1-5","lat":34.289906,"lng":133.799597,"geo_status":"db","era":"大正11年／昭和47年・令和元年移築","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"石造、高さ7.8m、基壇付","structure_material":"石造","registered":"2026.07.09(令和8.07.09)","register_no":"37 - 0496","desc":"丸亀護国神社境内に建つ明治天皇の行幸記念碑。総高７・８メートル。基壇中央の台座に立つ花崗岩製角柱頂部に銅製鳳凰像を飾る。角柱正面に碑文、上端に円形と紐を組合わせた装飾を付す。装飾抑えつつ格調を高めた外観で、地元の寄付金を用いて建てた記念碑。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016742"},{"id":"00005377","register_sub_id":"101","register_pk":"106365","name":"山田家（旧清酒源氏正宗醸造元）儀兵衛地蔵堂","kana":"やまだけ（きゅうせいしゅげんじまさむねじょうぞうもと）ぎへえじぞうどう","category":"その他","subcategory":"建築物","type_guess":"倉庫・蔵","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県高松市牟礼町牟礼字落合3129","lat":34.35297837,"lng":134.12952026,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積2.3㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0297","desc":"四国霊場八十五番札所八栗寺の表古参道に位置し，山田家長屋門の西南方に北面して建つ。方１間，宝形造，桟瓦葺の堂で，内部に享保１４年と明和２年を刻む地蔵２体を安置する。外壁３面の腰は縦板張，上部漆喰塗とした簡素な堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005377"},{"id":"00002463","register_sub_id":"101","register_pk":"103453","name":"山田家（旧清酒源氏正宗醸造元）灯篭","kana":"やまだけ（きゅうせいしゅげんじまさむねじょうぞうもと）とうろう","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県高松市牟礼町牟礼3186","lat":34.3524928,"lng":134.13018646,"geo_status":"db","era":"弘化5","year":1847,"year_source":"db","year_min":1847,"year_max":1847,"year_label":null,"structure":"石造、高さ3.0m","structure_material":"石造","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0079","desc":"屋敷地へのアプローチ道路入口に建つ常夜燈。聖天さんと親しまれる八栗寺参道沿いに在って八栗寺への道しるべとなる。胴部の参道沿いの南面には施主である主人「山田徳右衛門」の名を，東面には「聖天舎」を刻んで建立の由来を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002463"},{"id":"00002183","register_sub_id":"101","register_pk":"103173","name":"梅錦山川仕込蔵","kana":"うめにしきやまかわしこみぐら","category":"その他","subcategory":"建築物","type_guess":"倉庫・蔵","type_guess_confidence":"low","period":"江戸","pref":"愛媛県","address":"愛媛県四国中央市金田町金川14","lat":33.98895346,"lng":133.59402327,"geo_status":"db","era":"江戸末期／明治中期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積184㎡","structure_material":"土蔵造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"38 － 0014","desc":"主屋の南方に建つ南北棟，寄棟造，本瓦葺のやや規模の大きな平入の仕込蔵で，西面を旧道沿いに，南面を金生川支流三角寺川沿いにみせる。腰を竪板張りとし，小さな開口を２段千鳥に配して特徴ある正面をつくる。もと伊予西条藩御船蔵を移築したものと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002183"},{"id":"00002313","register_sub_id":"101","register_pk":"103303","name":"鍵谷カナ頌功堂","kana":"かぎやかなしょうこうどう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県松山市西垣生町1253","lat":33.81327024,"lng":132.70400284,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積39㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"38 － 0017","desc":"伊予絣創始者の鍵谷カナの功績を讃え伊予織物同業組合が建設。設計は木子七郎。鉄筋コンクリート造の八角堂で，中央に頌功碑を納める。８本のエンタシスの柱と斗組により反りの強い本瓦葺八角屋根を支える特徴的な姿形をしていることで知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002313"},{"id":"00003723","register_sub_id":"101","register_pk":"104713","name":"旧正野谷桟橋","kana":"きゅうしょうのだにさんばし","category":"その他","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県西宇和郡伊方町正野地先","lat":33.35896696,"lng":132.03507641,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造及び石造、延長73m","structure_material":"鉄筋コンクリート造及び石造","registered":"2003.12.01(平成15.12.01)","register_no":"38 － 0052","desc":"町南西部の佐田岬先端近くで宇和海に突き出た旧軍用桟橋。計２４本の円柱に支えられ，表面をモルタル洗出しとした係船柱付のＲＣ造構造物が，緑泥変岩を矢筈積風とした石垣と接続し，接続部の橋台上には花崗岩を配す。軍艦波止の愛称で住民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003723"},{"id":"00003150","register_sub_id":"101","register_pk":"104140","name":"旧鈍川小学校二宮金次郎像台座","kana":"きゅうにぶかわしょうがっこうにのみやきんじろうぞうだいざ","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県今治市玉川町鈍川丙245-1","lat":33.98567772,"lng":132.95744724,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"石造及びコンクリート造、面積7.5㎡","structure_material":"石造及びコンクリート造","registered":"2003.01.31(平成15.01.31)","register_no":"38 － 0027","desc":"鈍川運動公園の一角に建つ。当時の校長，教師，児童が学校下の玉川から川原石を拾い集め，富士山状に積み上げたもの。底辺４ｍ，高３ｍ規模の玉石練積の三角錐状台座で，正面に「恩」の字を刻んだレリーフを積み込む。鈍川地区のシンボル的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003150"},{"id":"00014541","register_sub_id":"101","register_pk":"513955","name":"旧陸軍歩兵第四四連隊講堂","kana":"きゅうりくぐんほへいだいよんじゅうよんれんたいこうどう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県高知市曙町二丁目960-3","lat":33.54923056,"lng":133.48400278,"geo_status":"db","era":"明治後期／昭和中期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、鉄板葺、建築面積248㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"39 - 0307","desc":"市西部の旧陸軍跡地に東面して建つ。木造平屋建、寄棟造平入で、外装は下見板張白色塗装とする。小屋組はキングポスト・トラス、内壁は竪板張目板打、一間幅の窓を密に配して採光を確保する。当初は３室に分かれ、下士官の学科教育用に建てた質実な陸軍建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014541"},{"id":"00014540","register_sub_id":"101","register_pk":"513954","name":"旧陸軍歩兵第四四連隊弾薬庫","kana":"きゅうりくぐんほへいだいよんじゅうよんれんたいだんやくこ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県高知市曙町二丁目960-3","lat":33.54988889,"lng":133.48409167,"geo_status":"db","era":"明治後期／昭和中期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造平屋建、瓦葺、建築面積156㎡","structure_material":"煉瓦造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"39 - 0306","desc":"市西部の旧陸軍跡地に東面して建つ。煉瓦造平屋建、寄棟造平入、正面板壁と引戸の下屋を付す。外壁約五〇センチ厚、内部は板張天井で板敷の三室を並べ、高床として湿気を抑え、出入口の欠円アーチ形両開き戸を鉄板で覆う。ほぼ完存する貴重な明治期の弾薬庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014540"},{"id":"00004442","register_sub_id":"101","register_pk":"105432","name":"料亭得月楼客間","kana":"りょうていとくげつろうきゃくま","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県高知市南はりまや町1-17-3","lat":33.558846,"lng":133.544235,"geo_status":"db","era":"昭和12／昭和25移築","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0156","desc":"本館の東南方に位置し，待合いを兼ねた渡り廊下で連絡する。桁行４間半梁間４間半，切妻造，桟瓦葺の木造平屋建で，南妻面を庭園に見せて建つ。６畳と８畳座敷から成り，北に便所と納戸を配し，四周に半間廊下を廻す。もと南国博覧会の営林局出品館を移築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004442"},{"id":"00015110","register_sub_id":"101","register_pk":"529388","name":"旧佐世保海軍工廠川棚魚雷遠距離発射場観測所","kana":"きゅうさせぼかいぐんこうしょうかわたなぎょらいえんきょりはっしゃじょうかんそくしょ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県東彼杵郡川棚町三越郷字片島174","lat":33.04814722,"lng":129.84388333,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"煉瓦造及び鉄筋コンクリート造2階建、建築面積19㎡","structure_material":"煉瓦造及び鉄筋コンクリート造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"42 - 0145","desc":"発射場が位置する片島の山頂に位置し、魚雷試射後の雷跡を観測する建物。二階建の煉瓦壁体の頂部に鉄筋コンクリート造の梁とスラブを廻らし、二階正面には広角に開いた観測用の窓を突出して海を望む。建物の機能を直裁的に造形化した特徴的な外観の軍事遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015110"},{"id":"00015108","register_sub_id":"101","register_pk":"529386","name":"旧佐世保海軍工廠川棚魚雷遠距離発射場機械室及び水雷調整室","kana":"きゅうさせぼかいぐんこうしょうかわたなぎょらいえんきょりはっしゃじょうきかいしつおよびすいらいちょうせいしつ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県東彼杵郡川棚町三越郷字片島151-1","lat":33.04898333,"lng":129.842775,"geo_status":"db","era":"大正7年頃／昭和14年増築","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造及び煉瓦造平屋建、建築面積330㎡","structure_material":"石造及び煉瓦造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"42 - 0143","desc":"突堤と正対して建ち、魚雷用の燃料及び酸化剤などを搭載し、調整した施設。正面一二メートル、奥行二七メートルで、下部は石造で内部を水雷調整室と機械室の二室に区画する。上部は後の増築で壁体を鉱滓煉瓦積とする。機能と建設技術において貴重な軍事遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015108"},{"id":"00015106","register_sub_id":"101","register_pk":"529384","name":"旧佐世保海軍工廠川棚魚雷遠距離発射場射場","kana":"きゅうさせぼかいぐんこうしょうかわたなぎょらいえんきょりはっしゃじょうしゃじょう","category":"その他","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県東彼杵郡川棚町三越郷字片島地先","lat":33.04893333,"lng":129.84190556,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"発射場 コンクリート造、面積276㎡、発射場上屋付（煉瓦造及び鉄筋コンクリート造3階建、建築面積6.5㎡）","structure_material":"発射場 コンクリート造","registered":"2024.08.15(令和6.08.15)","register_no":"42 - 0141","desc":"大村湾北部に位置する旧魚雷試射専用施設。陸地から約五〇メートル離れた海中に、コンクリートブロックで構築した矩形の人工島で、魚雷発射用の切込みを設け、煉瓦壁体と鉄筋コンクリート造屋根スラブ等からなる上屋や軌道敷を残す。全国的に希少な軍事遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015106"},{"id":"00015107","register_sub_id":"101","register_pk":"529385","name":"旧佐世保海軍工廠川棚魚雷遠距離発射場突堤","kana":"きゅうさせぼかいぐんこうしょうかわたなぎょらいえんきょりはっしゃじょうとってい","category":"その他","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県東彼杵郡川棚町三越郷字片島地先","lat":33.04899167,"lng":129.84221389,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"コンクリート造5連アーチ橋、橋長45m、幅員3.6m","structure_material":"コンクリート造5連アーチ橋","registered":"2024.08.15(令和6.08.15)","register_no":"42 - 0142","desc":"射場と陸地を結ぶために海中に築いた突堤。形状の異なるコンクリートブロックで積み上げた、長さ四五メートル、スパン八メートルの扁平な五連アーチ構造物。天端には二線の引込線跡を残す。コンクリートブロックを自在に成形して築いた独特な大規模構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015107"},{"id":"00015109","register_sub_id":"101","register_pk":"529387","name":"旧佐世保海軍工廠川棚魚雷遠距離発射場油庫","kana":"きゅうさせぼかいぐんこうしょうかわたなぎょらいえんきょりはっしゃじょうゆこ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県東彼杵郡川棚町三越郷字片島174","lat":33.048725,"lng":129.84269722,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造平屋建、建築面積20㎡","structure_material":"石造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"42 - 0144","desc":"機械室及び水雷調整室の南側に建つ燃料用の格納庫。桁行五・五メートル、梁間三・七メートル、切妻造、妻入の石造平屋建で、内壁はモルタル塗で仕上げる。凝灰岩を精緻に積上げ、隅部を算木積で築く、丁寧なつくり。魚雷試射システムに欠かせない施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015109"},{"id":"00010381","register_sub_id":"101","register_pk":"199153","name":"金剛庫","kana":"こんごうこ","category":"その他","subcategory":"建築物","type_guess":"倉庫・蔵","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県平戸市鏡川町字御舘13-3","lat":33.373307,"lng":129.553016,"geo_status":"db","era":"江戸末期／明治前期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積100㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"42-0119","desc":"松浦史料博物館の北方に南北棟で南面して建つ。二階建の土蔵で、桁行五間梁間二間半、切妻造桟瓦葺とし、正面入口に下屋を設ける。外壁は竪板張で、正面の扉には鉄板を張る。城内の土蔵を移築したと伝わり、藩政期の平戸城に由来する希少な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010381"},{"id":"00000420","register_sub_id":"101","register_pk":"101410","name":"佐世保市民文化ホール（旧海軍佐世保鎮守府凱旋記念館）","kana":"させぼしみんぶんかほーる（きゅうかいぐんさせぼちんじゅふがいせんきねんかん）","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県佐世保市平瀬町２","lat":33.17374274,"lng":129.71490706,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造2階建，鉄板葺，建築面積826㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"42 － 0007","desc":"第１次世界大戦の鎮守府所属艦船の武勲をたたえるため，九州・四国各県の寄付で建設された。鉄筋コンクリート造２階建で，妻を正面にみせた左右対称の外観，１・２階を通した柱，幾何学的な装飾等に特徴がある。海軍ゆかりの町の象徴として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000420"},{"id":"00009560","register_sub_id":"101","register_pk":"194353","name":"島原城御馬見所","kana":"しまばらじょうおんうまみしょ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県島原市城内1-1183-1","lat":32.7895347,"lng":130.36754766,"geo_status":"db","era":"江戸末期／明治前期・昭和41年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、杉皮葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"42 － 0103","desc":"島原城の本丸、天守の北東側に西面して建つ。桁行六・九メートル梁間三・四メートル、切妻造杉皮葺で、四畳半二室を畳廊下の南北に配し、西面を開放する。もとは三の丸の調練所に所在し、藩主が藩士の訓練状況視察に使用した。近世の馬見所として希な遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009560"},{"id":"00010382","register_sub_id":"101","register_pk":"199154","name":"仙禽庫","kana":"せんきんこ","category":"その他","subcategory":"建築物","type_guess":"倉庫・蔵","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県平戸市鏡川町字御舘13-3","lat":33.373236,"lng":129.553111,"geo_status":"db","era":"江戸末期／明治前期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積126㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"42-0120","desc":"松浦史料博物館の北方に金剛庫と並んで東西棟で南面して建つ。二階建の土蔵で、桁行六間梁間二間半、寄棟造桟瓦葺、平入とし、正面入口に下屋を設ける。床高が高く、防湿に配慮されており、平戸城内の文庫を移築したという伝承に相応しい仕様となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010382"},{"id":"00002342","register_sub_id":"101","register_pk":"103332","name":"旧佐伯海軍航空隊掩体壕","kana":"きゅうさえきかいぐんこうくうたいえんたいごう","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大分県","address":"大分県佐伯市東浜1-6","lat":32.96908759,"lng":131.91636403,"geo_status":"db","era":"昭和18","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"鉄筋コンクリート造、建築面積225㎡","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"44 － 0068","desc":"面積２２５㎡の鉄筋コンクリート造で，矩形の開口部で縁取ったヴォールト構造部分の後方に，尾翼を収納するためのほぼ半円筒状の構造体が付く特徴的な形態をもつ。戦時耐弾構造物の一例で，旧海軍航空機の防空用格納施設として広く知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002342"},{"id":"00012267","register_sub_id":"101","register_pk":"353068","name":"細島験潮場","kana":"ほそしまけんちょうじょう","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県日向市大字細島（細島商業港）","lat":32.428627,"lng":131.669579,"geo_status":"db","era":"明治26年／大正12年・昭和13年改修","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積6.1㎡","structure_material":"煉瓦造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"45-93","desc":"継続的な潮位観測のため陸地測量部によって設置された験潮場の建屋。現在の建屋は明治二六年のもの。切妻造妻入の煉瓦造で、屋根は桟瓦葺。内部は前室と観測室からなり、観測室に井戸が設けられている。我が国における潮位観測の歴史を今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012267"},{"id":"00006565","register_sub_id":"101","register_pk":"107548","name":"旧陸軍知覧飛行場弾薬庫","kana":"きゅうりくぐんちらんひこうじょうだんやくこ","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"鹿児島県","address":"鹿児島県南九州市知覧町郡17919-1","lat":31.36138709,"lng":130.43483764,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積8.7㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"46 － 0042","desc":"旧知覧飛行場（現知覧平和公園）の北東に造られ，桁行２．８ｍ，梁間２．４ｍ，壁厚２６ｃｍの規模で，鉄筋コンクリート造平屋建とする。木造の切妻屋根とし，内壁を板張としていた。小規模であるが，当時の弾薬庫の特徴を今日に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006565"},{"id":"00006564","register_sub_id":"101","register_pk":"107547","name":"旧陸軍知覧飛行場着陸訓練施設鎮碇","kana":"きゅうりくぐんちらんひこうじょうちゃくりくくんれんしせつちんてい","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"鹿児島県","address":"鹿児島県南九州市知覧町郡17885-3","lat":31.36389961,"lng":130.43302495,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"鉄筋コンクリート造、高さ2.3m、面積70㎡","structure_material":"鉄筋コンクリート造","registered":"2007.07.31(平成19.07.31)","register_no":"46 － 0043","desc":"旧知覧飛行場（現知覧平和公園）の西方に造られた，着陸訓練用のロープを固定したＲＣ造の鎮碇である。南北１０ｍ，東西６ｍの床部を築き，中央やや西寄りに脚部２つを立て，ロープを固定した梁で両者を繋ぐ。当時の飛行訓練施設の状況を知る貴重な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006564"},{"id":"00006566","register_sub_id":"101","register_pk":"107549","name":"旧陸軍知覧飛行場防火水槽","kana":"きゅうりくぐんちらんひこうじょうぼうかすいそう","category":"その他","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"鹿児島県","address":"鹿児島県南九州市知覧町郡17932","lat":31.36037553,"lng":130.43561204,"geo_status":"db","era":"昭和16／平成16移設","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"コンクリート造、面積93㎡","structure_material":"コンクリート造","registered":"2007.07.31(平成19.07.31)","register_no":"46 － 0041","desc":"旧知覧飛行場（現知覧平和公園）の北東に造られたコンクリート造の防火水槽である。直径１０ｍの円形で，周囲を１ｍ立ち上げ，すり鉢状で中央の深さを２ｍとし，底面に中央に向かって３方向から階段を付ける。往時の飛行場施設のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006566"},{"id":"00002343","register_sub_id":"101","register_pk":"103333","name":"仙巌園内濾過池","kana":"せんがんえんないろかち","category":"その他","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"鹿児島県","address":"鹿児島県鹿児島市吉野町9700-1","lat":31.6189988,"lng":130.58152083,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"石造平屋建、建築面積21㎡、深さ2.4m","structure_material":"石造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"46 － 0007","desc":"市街の北部，鹿児島湾を臨む名勝仙巌園の隣接地に所在する。地下約２．４ｍの位置に布設された水道石管から取水し，ろ過の後に敷地内各所に配水する。大型切石積の壁面から石造ヴォールト天井を架け，外観は和風を意識した切妻屋根に見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002343"},{"id":"00002345","register_sub_id":"101","register_pk":"103335","name":"山田の凱旋門","kana":"やまだのがいせんもん","category":"その他","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県姶良市下名1178","lat":31.77358119,"lng":130.61411907,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"石造、高さ4.7m、幅4.9m","structure_material":"石造","registered":"2001.08.28(平成13.08.28)","register_no":"46 － 0009","desc":"日露戦争従軍者の帰還を記念して山田村兵事会が建設。江戸切仕上の石を１５段，高４．７ｍに積んで門柱とし，約２．７ｍの門柱間に石アーチを架けて凱旋門風の構えを造る。小規模ながら，日本では類例の少ない恒久的凱旋門建造物として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002345"},{"id":"00001841","register_sub_id":"101","register_pk":"102831","name":"エドウィン・ダン記念館（旧北海道庁真駒内種畜場事務所）","kana":"えどうぃん・だんきねんかん（きゅうほっかいどうちょうまこまないしゅちくじょうじむしょ）","category":"産業1次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道札幌市南区真駒内泉町1-6-1","lat":42.98898587,"lng":141.35236232,"geo_status":"db","era":"明治20／昭和39移築","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積231㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"01 － 0027","desc":"農商務省所管の真駒内種畜場の事務所として同省北海道事業管理局が設計。下見板張，寄棟造で正面中央に切妻造の玄関及び屋根窓を構え，背後に両側面ベランダ付の部屋を増設。真駒内中央公園内に移築，畜産技術を指導したお雇い米国人ダンの記念館として公開。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001841"},{"id":"00007709","register_sub_id":"101","register_pk":"108691","name":"伝成館（旧北海道農事試験場根室支場庁舎）","kana":"でんせいかん（きゅうほっかいどうのうじしけんじょうねむろしじょうちょうしゃ）","category":"産業1次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道標津郡中標津町桜ヶ丘1-1-5","lat":43.54437448,"lng":144.97840253,"geo_status":"db","era":"昭和2／昭和32・平成5改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階建塔屋付、鉄板葺、建築面積255㎡","structure_material":"鉄筋コンクリート造2階建塔屋付","registered":"2009.08.07(平成21.08.07)","register_no":"01-0101","desc":"種苗倉庫の東南方に東面して建つ。南北２６ｍ東西９．０ｍの鉄筋コンクリート造２階建で、中央に塔屋を上げ玄関を張り出し、左右対称に縦長上下窓を配する。北海道第二期拓殖計画の一環として実施された根釧原野の開拓事業を象徴する建築物の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007709"},{"id":"00007710","register_sub_id":"101","register_pk":"108692","name":"中標津町郷土館緑ヶ丘分館（旧北海道農事試験場根室支場陳列館）","kana":"なかしべつちょうきょうどかんみどりがおかぶんかん（きゅうほっかいどうのうじしけんじょうねむろしじょうちんれつかん）","category":"産業1次","subcategory":"建築物","type_guess":"資料館","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道標津郡中標津町丸山4-3-1","lat":43.55834495,"lng":144.96072196,"geo_status":"db","era":"昭和3／昭和57移築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積109㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"01-0102","desc":"市街地の北方に位置する公園内に西面して建つ。桁行１５ｍ梁間７．３ｍ、寄棟造平入の木造平屋建。腰下見板張とし、切妻を見せる玄関を中心として左右対称に縦長上下窓を配する。玄関奥に風除室を設け、内部は一室とする。丁寧にデザインされた瀟洒な建築物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007710"},{"id":"00009248","register_sub_id":"101","register_pk":"194041","name":"沼田家住宅旧第二りんご倉庫","kana":"ぬまたけじゅうたくきゅうだいにりんごそうこ","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道札幌市豊平区西岡4条10-350-64","lat":43.00052228,"lng":141.38299496,"geo_status":"db","era":"昭和28年","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"煉瓦造平屋建、鉄板葺、建築面積36㎡","structure_material":"煉瓦造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"01 － 0123","desc":"札幌市東郊の水源地通りに面して建つ。桁行六・八メートル梁間五・二メートルの煉瓦造、切妻造鉄板葺。北面中央西寄りの欠円アーチ戸口上部に三角ペディメントを飾る。外壁に断熱のため中空層を設け、軒蛇腹は鋸歯形に作る。整った意匠の煉瓦造倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009248"},{"id":"00002190","register_sub_id":"101","register_pk":"103180","name":"根室市明治公園第一サイロ","kana":"ねむろしめいじこうえんだいいちさいろ","category":"産業1次","subcategory":"その他工作物","type_guess":"サイロ","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道根室市牧の内146-242","lat":43.33457517,"lng":145.59887325,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"煉瓦造、直径5.9m、高さ15m","structure_material":"煉瓦造","registered":"2001.08.28(平成13.08.28)","register_no":"01 － 0031","desc":"市街地北の明治公園芝生広場の中央部に建つ。高さ１５ｍ，直径約６ｍの煉瓦造サイロで，南側面に高さ１ｍの開口部を縦一列に４箇所穿つ。北側に出窓を設けた，こけし状ファイニアル付き鉄板葺ドーム形屋根を冠する。国内最大級規模の煉瓦造サイロ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002190"},{"id":"00002192","register_sub_id":"101","register_pk":"103182","name":"根室市明治公園第三サイロ","kana":"ねむろしめいじこうえんだいさんさいろ","category":"産業1次","subcategory":"その他工作物","type_guess":"サイロ","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道根室市牧の内146-242","lat":43.33488176,"lng":145.59838504,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"煉瓦造、直径5.9m、高さ14m","structure_material":"煉瓦造","registered":"2001.08.28(平成13.08.28)","register_no":"01 － 0033","desc":"第二サイロの西側に建つ。第一サイロと類似した外観を呈す。３基のサイロは，明治８年に開拓使根室牧畜場として拓かれ，大正１０年から北海道練乳会社（現明治乳業株式会社）が所有する土地に建設された。地域の歴史を示す遺構として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002192"},{"id":"00002191","register_sub_id":"101","register_pk":"103181","name":"根室市明治公園第二サイロ","kana":"ねむろしめいじこうえんだいにさいろ","category":"産業1次","subcategory":"その他工作物","type_guess":"サイロ","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道根室市牧の内146-242","lat":43.33499345,"lng":145.59871469,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"煉瓦造、直径4.7m、高さ12m","structure_material":"煉瓦造","registered":"2001.08.28(平成13.08.28)","register_no":"01 － 0032","desc":"第一サイロの北東側に建つ。他の２基より小規模で，出窓を西側に向けた尖頭ドーム形屋根を有する。南側面に矩形開口部を縦一列に３箇所設け，煉瓦壁体を小口と羊羹を交互に見せるフランス積風に積む。軒部は煉瓦２段を刎ねだして外観にアクセントを付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002191"},{"id":"00007708","register_sub_id":"101","register_pk":"108690","name":"北海道立根釧農業試験場（旧北海道農事試験場根室支場）種苗倉庫","kana":"ほっかいどうりつこんせんのうぎょうしけんじょう（きゅうほっかいどうのうじしけんじょうねむろしじょう）しゅびょうそうこ","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道標津郡中標津町桜ヶ丘1-1-3","lat":43.54446351,"lng":144.97789967,"geo_status":"db","era":"昭和3／昭和58頃改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積79㎡","structure_material":"木造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"01-0100","desc":"農具庫の東方に南面して建つ。桁行１１ｍ梁間７．３ｍ、切妻造の木造２階建。内部を東西二室に分け、６０ｃｍの高さに床を張る。外壁は上部を下見板張とし、柱や窓などを白く塗る。正・背面各２ヵ所の屋根窓を設ける腰折屋根の外観が印象的な倉庫建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007708"},{"id":"00007707","register_sub_id":"101","register_pk":"108689","name":"北海道立根釧農業試験場（旧北海道農事試験場根室支場）農具庫","kana":"ほっかいどうりつこんせんのうぎょうしけんじょう（きゅうほっかいどうのうじしけんじょうねむろしじょう）のうぐこ","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"北海道","address":"北海道標津郡中標津町桜ヶ丘1-1-3","lat":43.5443591,"lng":144.97775206,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"01-0099","desc":"市街地の南方に広がる敷地に南面して建つ。桁行１０ｍ梁間７．３ｍ、切妻造平入の木造平屋建で、外装は妻上部を竪羽目板張とする他は下見板張とする。隅柱や窓枠、建具等を白色に塗り、四面に窓をまわす方形の塔屋を中央頂部に載せる特徴的な外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007707"},{"id":"00002189","register_sub_id":"101","register_pk":"103179","name":"北海道林木育種場旧庁舎","kana":"ほっかいどうりんぼくいくしゅじょうきゅうちょうしゃ","category":"産業1次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道江別市文京台緑町561-1","lat":43.07852427,"lng":141.52032262,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積744㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"01 － 0030","desc":"野幌森林公園内の北端部にある。北海道庁林業試験場として建設される。1階を煉瓦組積造，2階をハーフティンバー風木造とし，外装モルタル洗出とする。小屋組はクイーンポストトラス風。市の高台に位置し，地域のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002189"},{"id":"00009249","register_sub_id":"101","register_pk":"194042","name":"柳田家住宅旧りんご蔵","kana":"やなぎだけじゅうたくきゅうりんごくら","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道札幌市豊平区平岸2条5-9-1","lat":43.03779066,"lng":141.36892785,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造2階建、瓦葺、建築面積40㎡","structure_material":"煉瓦造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"01 － 0124","desc":"街路に北面して建つ桁行七・二メートル梁間五・五メートル煉瓦造二階建、切妻造桟瓦葺で、南妻面戸口に煉瓦造袖壁付の鉄板葺庇がつく。南妻の二階窓にモルタル塗袖壁付庇がある。外壁はイギリス積で軒蛇腹は歯飾りとする。草創期の煉瓦造りんご貯蔵庫である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009249"},{"id":"00014554","register_sub_id":"101","register_pk":"515096","name":"レースホース牧場（旧大日本競走馬生産）本厩舎","kana":"れーすほーすぼくじょう（きゅうだいにほんきょうそうばせいさん）ほんきゅうしゃ","category":"産業1次","subcategory":"建築物","type_guess":"厩舎","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道日高郡新ひだか町三石歌笛379","lat":42.30090556,"lng":142.67806944,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"煉瓦造及び木造2階建、鉄板葺、建築面積851㎡","structure_material":"煉瓦造及び木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"01 - 0165","desc":"神威岳南西麓に位置する競走馬牧場の厩舎。中央を二階建主玄関とし、南北に長大な鉄板葺の腰折れ屋根を架ける。内部一階北半を親馬、南半を子馬の馬房、小屋裏二階は一室の大空間で飼料置場、両妻を搬入口とする。長大な厩舎が馬産地の雄大な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014554"},{"id":"00001463","register_sub_id":"101","register_pk":"102453","name":"盛田牧場一号廏舎（南部曲屋育成廏舎）","kana":"もりたぼくじょういちごうきゅうしゃ（なんぶまがりやいくせいきゅうしゃ）","category":"産業1次","subcategory":"建築物","type_guess":"厩舎","type_guess_confidence":"high","period":"明治","pref":"青森県","address":"青森県上北郡七戸町字膝森14-1","lat":40.71021337,"lng":141.16872069,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、茅葺、建築面積368㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"02 － 0004","desc":"盛田牧場は，明治１７年の函館競馬開始後，まもなくアラブ馬中心にサラブレットも飼育する洋風牧場となった。一号厩舎は墨書より明治４５年５月建築とわかる最古の建物。長大で豪壮な茅葺屋根が，近代の牧場景観を伝えるものとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001463"},{"id":"00001467","register_sub_id":"101","register_pk":"102457","name":"盛田牧場五号廏舎（種牡馬廏舎）","kana":"もりたぼくじょうごごうきゅうしゃ（しゅぼばきゅうしゃ）","category":"産業1次","subcategory":"建築物","type_guess":"厩舎","type_guess_confidence":"high","period":"昭和前","pref":"青森県","address":"青森県上北郡七戸町字膝森5","lat":40.71063333,"lng":141.17004972,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2000.02.15(平成12.02.15)","register_no":"02 － 0008","desc":"四号厩舎と同じ昭和１５年に建てられた木造，平屋建，切妻造・鉄板葺の厩舎であるが，他の４棟より規模が小さく，平面も片通路式である。正面玄関には大きな切妻のペディメントをつけ，内外とも白ペンキ塗で仕上るなど，瀟洒な意匠でまとめられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001467"},{"id":"00001465","register_sub_id":"101","register_pk":"102455","name":"盛田牧場三号廏舎（繁殖廏舎）","kana":"もりたぼくじょうさんごうきゅうしゃ（はんしょくきゅうしゃ）","category":"産業1次","subcategory":"建築物","type_guess":"厩舎","type_guess_confidence":"high","period":"大正","pref":"青森県","address":"青森県上北郡七戸町字膝森14-1","lat":40.710258,"lng":141.17215,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積312㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"02 － 0006","desc":"中通路式の左右馬房配置の平面で，東端で鍵形に宿舎が取り付き，２階を飼料倉庫とする。墨書から大正９年と判明し，マンサード風鉄板葺は，当初は曲屋形式の茅葺であった。正面の飼料搬出口の切上げ部が高窓風に纏められ，均整の取れた外観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001465"},{"id":"00001464","register_sub_id":"101","register_pk":"102454","name":"盛田牧場二号廏舎（育成廏舎）","kana":"もりたぼくじょうにごうきゅうしゃ（いくせいきゅうしゃ）","category":"産業1次","subcategory":"建築物","type_guess":"厩舎","type_guess_confidence":"high","period":"大正","pref":"青森県","address":"青森県上北郡七戸町字膝森14-1","lat":40.71043068,"lng":141.16923536,"geo_status":"db","era":"大正12／昭和27増築","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積491㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"02 － 0005","desc":"一号厩舎の北東，差し掛け屋根で続く。木造２階建，鉄板葺で，東側マンサード屋根部分は昭和２７年の増築。一号厩舎と同じく，１階は中通路の左右に馬房を配した平面で，２階は飼料倉庫とする。下見板張の外壁と変形屋根は一号厩舎からの発展を物語っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001464"},{"id":"00001466","register_sub_id":"101","register_pk":"102456","name":"盛田牧場四号廏舎（繁殖廏舎）","kana":"もりたぼくじょうよんごうきゅうしゃ（はんしょくきゅうしゃ）","category":"産業1次","subcategory":"建築物","type_guess":"厩舎","type_guess_confidence":"high","period":"昭和前","pref":"青森県","address":"青森県上北郡七戸町字膝森5","lat":40.71025368,"lng":141.17258835,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積579㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"02 － 0007","desc":"木造，２階建，切妻造・鉄板葺で，昭和１５年に繁殖馬用厩舎として，三号厩舎北東に連続して建つ。中通路式平面で，東端には種付け部屋があり，さらに宿舎が突出する。雄大な規模ながら，外壁を下見板張とした素朴な外観で，機能重視への移行がうかがえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001466"},{"id":"00009573","register_sub_id":"101","register_pk":"194569","name":"旧釜石鉱山事務所","kana":"きゅうかまいしこうざんじむしょ","category":"産業1次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和中","pref":"岩手県","address":"岩手県釜石市甲子町第1地割90-2","lat":39.28610423,"lng":141.7149094,"geo_status":"db","era":"昭和26／昭和29増築","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積735㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"03 － 0082","desc":"鉄筋コンクリート造二階建の東西棟で陸屋根とする。平滑な外壁に欄間付の上下窓が規則正しく並び、北東隅の玄関と外壁上端に廻らせた庇がアクセントとなっている。一階東半は事務室で受付カウンターが残る。西端に倉庫等を増築。端正なモダニズム建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009573"},{"id":"00014706","register_sub_id":"101","register_pk":"518964","name":"旧佐々木家住宅板倉","kana":"きゅうささきけじゅうたくいたくら","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県石巻市北上町十三浜字吉浜403-3他","lat":38.57434444,"lng":141.44838611,"geo_status":"db","era":"明治中期／大正4年・令和4年移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、スレート葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"04 - 0216","desc":"北上川河口の丘陵頂部に移築したかつての米倉。平屋建切妻造妻入の東西棟で置屋根形式のスレート葺とし東妻を戸口として庇を付す。内部は１室の板敷で上部は二段に梁を重ねた和小屋を現す。側柱を密に立てた当地域特有の板蔵で小規模ながらも存在感を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014706"},{"id":"00014705","register_sub_id":"101","register_pk":"518963","name":"旧鈴木家住宅板倉","kana":"きゅうすずきけじゅうたくいたくら","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県石巻市北上町十三浜字吉浜403-16","lat":38.57469167,"lng":141.44957222,"geo_status":"db","era":"大正4年／令和4年移築","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"04 - 0215","desc":"北上川河口に移築したかつての米倉。平屋建切妻造妻入東西棟で置屋根形式のスレート葺とし南に下屋を付す。内部は一室の板敷で、上部に三段に梁を重ねた和小屋を現す。当地域に特有の板蔵で、庇の持送や置屋根の面戸板を精緻な彫刻で飾り大工の力量を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014705"},{"id":"00001824","register_sub_id":"101","register_pk":"102814","name":"秋田公立美術工芸短期大学実習棟一号棟","kana":"あきたこうりつびじゅつこうげいたんきだいがくじっしゅうとういちごうとう","category":"産業1次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県秋田市新屋大川町12-3","lat":39.68601049,"lng":140.090317,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積660㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"05 － 0057","desc":"旧秋田県販売購買組合連合会（現秋田経済連）が雄物川河口付近に建設した８棟の木造平屋建の倉庫群のひとつで，その最北端に位置する。倉庫群は，昭和１４年に政府に寄付されて「国立新屋倉庫」となり，平成２年まで米の需給倉庫として用いられた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001824"},{"id":"00001826","register_sub_id":"101","register_pk":"102816","name":"秋田公立美術工芸短期大学実習棟三号棟","kana":"あきたこうりつびじゅつこうげいたんきだいがくじっしゅうとうさんごうとう","category":"産業1次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県秋田市新屋大川町12-3","lat":39.6856641,"lng":140.09033851,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積660㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"05 － 0059","desc":"切妻造の東西棟が軒を接するように建ち並ぶ８棟の倉庫群のうち北から第３に位置する。平成６年に短期大学用地として秋田市に譲渡された。北から第１～３棟は内部を改築して工芸美術・産業デザインの実習棟として使用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001826"},{"id":"00001825","register_sub_id":"101","register_pk":"102815","name":"秋田公立美術工芸短期大学実習棟二号棟","kana":"あきたこうりつびじゅつこうげいたんきだいがくじっしゅうとうにごうとう","category":"産業1次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県秋田市新屋大川町12-3","lat":39.68584249,"lng":140.09033361,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積660㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"05 － 0058","desc":"雄物川改修工事（大正６年～昭和１３年）に伴う廃土による埋め立て地に建設された８棟の倉庫群のひとつで，北から２番目に位置する。平成２年に農業倉庫としての用途を廃止し，北から第１～７棟は秋田公立美術工芸短期大学のユニークなキャンパス施設となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001825"},{"id":"00001830","register_sub_id":"101","register_pk":"102820","name":"秋田公立美術工芸短期大学創作工房棟","kana":"あきたこうりつびじゅつこうげいたんきだいがくそうさくこうぼうとう","category":"産業1次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県秋田市新屋大川町12-3","lat":39.68498361,"lng":140.0904439,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積660㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"05 － 0063","desc":"倉庫群のうち北から第７に位置する。各棟の外観は土蔵造風とし，屋根は保温のため野小屋を設けており置屋根形式風となる。大学施設への転用に際して，妻壁や側壁面に明かり窓を設け，各所の越屋根を一連に繋ぐなどの改築はあるが当初の面影を良く伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001830"},{"id":"00001828","register_sub_id":"101","register_pk":"102818","name":"秋田公立美術工芸短期大学大学開放センターギャラリー棟","kana":"あきたこうりつびじゅつこうげいたんきだいがくだいがくかいほうせんたーぎゃらりーとう","category":"産業1次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県秋田市新屋大川町12-3","lat":39.68533551,"lng":140.09037013,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積660㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"05 － 0061","desc":"倉庫群のうち北から第５に位置する。各倉庫の内部はもと東西２室に分かれ，各室とも中央に２列の柱を立てて通路とした。小屋組は中央柱列間を方杖で補強した和小屋，両脇を三角ハウトラスとする和洋の複合構造で，長大なスパンに対応した独創的な形式とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001828"},{"id":"00001827","register_sub_id":"101","register_pk":"102817","name":"秋田公立美術工芸短期大学大学開放センター工芸体験棟","kana":"あきたこうりつびじゅつこうげいたんきだいがくだいがくかいほうせんたーこうげいたいけんとう","category":"産業1次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県秋田市新屋大川町12-3","lat":39.68550559,"lng":140.09035543,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積660㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"05 － 0060","desc":"８棟の倉庫群のうち北から第４に位置する。各倉庫はいずれも桁行４５ｍ梁間１５ｍと同一規模で，木造平屋建，モルタル塗，切妻造妻入りで，棟上に換気用の越屋根を備える。西面に入り口の庇，東面に鉄道引込線プラットフォームの通し庇が付く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001827"},{"id":"00001829","register_sub_id":"101","register_pk":"102819","name":"秋田公立美術工芸短期大学大学開放センター地域交流棟","kana":"あきたこうりつびじゅつこうげいたんきだいがくだいがくかいほうせんたーちいきこうりゅうとう","category":"産業1次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県秋田市新屋大川町12-3","lat":39.6851721,"lng":140.09040441,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積660㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"05 － 0062","desc":"８棟が建ち並ぶ倉庫群のうち，北から第６に位置する。北から第４～６棟は内部を改築し，それぞれ大学開放センターの工芸体験棟，ギャラリー棟，地域交流棟として開放されている。展示場・多目的ホール・休憩施設が設けられ，市民講座や体験学習が行われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001829"},{"id":"00001831","register_sub_id":"101","register_pk":"102821","name":"秋田市立新屋図書館倉庫棟","kana":"あきたしりつあらやとしょかんそうことう","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県秋田市新屋大川町12-26","lat":39.68480182,"lng":140.09046602,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積660㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"05 － 0064","desc":"８棟の倉庫群のうち最南端に位置して，現在は秋田市立の図書館の倉庫として用いられている。秋田公立美術工芸短期大学施設として活用された７棟と併せて，揃って保存・活用が図られており，昭和前期の大型木造倉庫が軒を連ねた姿を良く伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001831"},{"id":"00015131","register_sub_id":"101","register_pk":"530555","name":"関田円型分水工","kana":"せきたえんけいぶんすいこう","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県仙北郡美郷町六郷東根字上関田172-1","lat":39.41637778,"lng":140.58455278,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造、面積123㎡","structure_material":"鉄筋コンクリート造","registered":"2024.12.03(令和6.12.03)","register_no":"05 - 0259","desc":"雄物川水系丸子川上流、六郷扇状地の扇頂部に位置する、鉄筋コンクリート造、直径一二メートルの円型分水工。内円筒の一八〇個の分水孔から流す水を、外円筒の仕切板で一〇の地域に分水。美郷町の稲作を支える農業施設で、円型分水工の初期事例としても貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015131"},{"id":"00014313","register_sub_id":"101","register_pk":"511302","name":"旧松岡家住宅馬屋","kana":"きゅうまつおかけじゅうたくうまや","category":"産業1次","subcategory":"建築物","type_guess":"厩舎","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県長井市歌丸字窪二1629","lat":38.05585278,"lng":140.02713333,"geo_status":"db","era":"昭和7年／昭和中期改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積32㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"06 - 0206","desc":"主屋の北隣に東面し、かつて牛馬を飼育した馬屋。つし二階建、切妻造平入で背面葺下す。屋根は鉄板葺で元茅葺。外壁は漆喰仕上で内法下を板張とする。内部は東に土間、西に二馬房を並べ、土間境にマセ棒受けの柱が立つ。主屋と一体で歴史的景観をつくる馬屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014313"},{"id":"00014314","register_sub_id":"101","register_pk":"511303","name":"旧松岡家住宅作業小屋及び牛舎","kana":"きゅうまつおかけじゅうたくさぎょうごやおよびぎゅうしゃ","category":"産業1次","subcategory":"建築物","type_guess":"厩舎","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市歌丸字窪二1629","lat":38.05584722,"lng":140.02730833,"geo_status":"db","era":"明治41年／昭和中期増築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積68㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"06 - 0207","desc":"主屋の北東に位置し、農機具を収納する作業小屋及びかつて乳牛を飼育した牛舎。平屋建、切妻造、鉄板仮葺（茅葺）の作業小屋の北側に、切妻造、鉄板葺の牛舎が接続し、北と西に下屋を付す。南北棟が前蔵と連なって、屋敷地正面の歴史的農村景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014314"},{"id":"00011241","register_sub_id":"101","register_pk":"209076","name":"蔵楽（旧宮内繭市場繭蔵）一号館","kana":"くらら（きゅうみやうちまゆしじょうまゆぐら）１ごうかん","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県南陽市宮内字穴田三 1003-4","lat":38.070537,"lng":140.137562,"geo_status":"db","era":"大正11頃／平成15改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"土蔵造3階建、鉄板葺、建築面積292㎡","structure_material":"土蔵造3階建","registered":"2016.11.29(平成28.11.29)","register_no":"06－0177","desc":"敷地に三棟残る大規模繭倉庫の一つ。すべて棟は南北方向で平入、切妻置屋根で東側に窓を多数配置する。1号館は三棟のうち最も古く、残りもよい。敷地南西に建つ土蔵造三階建で、軒下には比較的単純な鉢巻を設ける。蚕糸業で栄えた置賜地域の歴史を伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011241"},{"id":"00011242","register_sub_id":"101","register_pk":"209077","name":"蔵楽（旧宮内繭市場繭蔵）二号館","kana":"くらら（きゅうみやうちまゆしじょうまゆぐら）２ごうかん","category":"産業1次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県南陽市宮内字穴田三 1003-4他","lat":38.07098,"lng":140.137578,"geo_status":"db","era":"大正後期／平成15改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"鉄筋コンクリート造2階建、鋼板葺、建築面積292㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"06－0178","desc":"敷地北西側に建つ。南北棟、鋼板葺置屋根形式の平入で、東面に多数の窓を設ける。一号館とほぼ同規模で、小屋組をキングポストトラスとする点も同様だが、構造は鉄筋コンクリート造。特異な外観を持つ大規模倉庫で、蚕糸業で栄えた置賜地域の歴史を今日に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011242"},{"id":"00011243","register_sub_id":"101","register_pk":"209078","name":"蔵楽（旧宮内繭市場繭蔵）三号館","kana":"くらら（きゅうみやうちまゆしじょうまゆぐら）３ごうかん","category":"産業1次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県南陽市宮内字穴田三 1003-4他","lat":38.071035,"lng":140.137862,"geo_status":"db","era":"昭和2／平成15改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階建、鉄板葺、建築面積581㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"06－0179","desc":"敷地に三棟残る大規模な繭倉庫の一つ。敷地北側中央に建つ三号館は三棟のうち最大で桁行三八メートル、梁間一五メートル。南北棟の平入、切妻屋根で東側に窓を多数配する。小屋組はクイーンポストトラス。蚕糸業で栄えた地域の歴史を伝える大規模倉庫である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011243"},{"id":"00011246","register_sub_id":"101","register_pk":"209081","name":"夕鶴の里資料館（旧多勢丸多製糸場繭蔵）","kana":"ゆうづるのさとしりょうかん（きゅうたせまるたせいしじょうまゆぐら）","category":"産業1次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県南陽市漆山北目2021他","lat":38.07063068,"lng":140.12075102,"geo_status":"db","era":"大正11頃／昭和50代移築","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"土蔵造3階建、鉄板葺、建築面積263㎡","structure_material":"土蔵造3階建","registered":"2016.11.29(平成28.11.29)","register_no":"06－0182","desc":"明治から昭和に隆盛を極めた多勢丸多製糸場の繭蔵。桁行二三メートル、梁間一一メートル。屋根は置屋根形式。東側に窓を多数設ける。棟通りに丸太の大径材を用いた柱を五本並べ、クイーンポストトラスの小屋組を支えるなど、豪壮な架構が往時の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011246"},{"id":"00014736","register_sub_id":"101","register_pk":"518994","name":"旧吉田村農業協同組合西倉庫（吉田村Village西棟）","kana":"きゅうよしだむらのうぎょうきょうどうくみあいにしそうこ（よしだむらびれっじにしとう）","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県下野市本吉田字沼端784-1他","lat":36.37397222,"lng":139.91045,"geo_status":"db","era":"昭和前期／令和元年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"石造平屋建、瓦葺、建築面積248㎡","structure_material":"石造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"09 - 0274","desc":"鬼怒川右岸に所在する旧農協の穀物倉庫。石造平屋建切妻造セメント瓦葺で内部は元は三室で北面三箇所に欠円アーチ戸口、上部に庇付小窓を開く。外壁は大谷石切石積で軒に鉢巻を廻し、下部六箇所にバットレスを付す。小屋組はトラス組。地域色豊かな石造倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014736"},{"id":"00014737","register_sub_id":"101","register_pk":"518995","name":"旧吉田村農業協同組合東倉庫（吉田村Village東棟）","kana":"きゅうよしだむらのうぎょうきょうどうくみあいひがしそうこ（よしだむらびれっじひがしとう）","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"栃木県","address":"栃木県下野市本吉田字沼端784-1他","lat":36.373975,"lng":139.91071389,"geo_status":"db","era":"昭和中期／令和5年改修","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"石造平屋建、瓦葺、建築面積186㎡","structure_material":"石造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"09 - 0275","desc":"西倉庫東に建つ旧農協の穀物倉庫。石造平屋建、屋根は切妻造セメント瓦葺。北面二箇所に戸口を開き、北面東に小部屋を突出。外壁は大谷石切石積で控壁と臥梁、妻壁上部を鉄筋コンクリート造とする。小屋組は吊束二対のキングポスト・トラス。補強石造の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014737"},{"id":"00004944","register_sub_id":"101","register_pk":"105934","name":"小川家住宅蚕室","kana":"おがわけじゅうたくかいこしつ","category":"産業1次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県太田市安養寺町93-1","lat":36.26013204,"lng":139.30787924,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、鉄板葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0147","desc":"主屋と長屋門の間，東寄りに建つ。南北棟の切妻造平屋建で，棟中央には切妻造の「カンキマド」を設け，周囲に下屋を廻す。稚蚕飼育を行い，桑場として用いられたという。近代の生業に関連した施設で，当地方の養蚕施設の在り様を示す事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004944"},{"id":"00003805","register_sub_id":"101","register_pk":"104795","name":"小茂田家住宅蚕室","kana":"こもだけじゅうたくかいこしつ","category":"産業1次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県伊勢崎市長沼町2631","lat":36.262379,"lng":139.212402,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積141㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0103","desc":"屋敷地の東南方，門右手に位置し，南北棟で建つ。桁行１０間梁間２間半，切妻造，桟瓦葺の木造２階建で，正面に１間半幅の下屋を差し掛ける。南側は半地下状とし，蚕種貯蔵用の室となっている。蚕種・養蚕農家の発展過程を物語る遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003805"},{"id":"00000234","register_sub_id":"101","register_pk":"101224","name":"浦和くらしの博物館民家園展示棟（旧浦和市農業協同組合三室支所倉庫）","kana":"うらわくらしのはくぶつかんみんかえんてんじとう（きゅううらわしのうぎょうきょうどうくみあいみむろししょそうこ）","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県さいたま市緑区大字下山口新田1179-1","lat":35.87830467,"lng":139.71048244,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造平屋建，瓦葺，建築面積197㎡","structure_material":"石造平屋建","registered":"1997.07.15(平成9.07.15)","register_no":"11 － 0003","desc":"大谷石の積石の上部に木造の土蔵をのせた平屋建の倉庫。元は栃木県小山市の小山駅前に建てられたが、昭和３１年に浦和市に移築され、さらに平成に入って現在地に移された。石造と漆喰のコントラストをなす外観が特徴的で、広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000234"},{"id":"00001902","register_sub_id":"101","register_pk":"102892","name":"間瀬堰堤","kana":"まぜえんてい","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県本庄市児玉町小平地内","lat":36.16058951,"lng":139.1084104,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長126m、堤高28m、取水塔・護岸堤防付","structure_material":"重力式コンクリート造堰堤","registered":"2000.10.18(平成12.10.18)","register_no":"11 － 0026","desc":"大正8年～昭和13年にかけて造られた児玉用水の中心的施設で，堤長126m，堤高28m，取水塔付のコンクリート造重力式堰堤。木造2階建の取水塔上屋附属。堤体内に放水路を設け，洪水吐導流部を中央越流式とする。天端の高欄に擬木を用いる。設計は高堀育三。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001902"},{"id":"00001903","register_sub_id":"101","register_pk":"102893","name":"間瀬堰堤管理橋","kana":"まぜえんていかんりきょう","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県本庄市児玉町小平地内","lat":36.16357096,"lng":139.10931985,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造桁橋、橋長9.5m、幅員2.0m","structure_material":"鉄筋コンクリート造桁橋","registered":"2000.10.18(平成12.10.18)","register_no":"11 － 0027","desc":"間瀬川中流部に建設された農業用ダム・間瀬堰堤の導水下流部に架かる。３径間ＲＣ造桁橋で，下部をアーチ形に刳り抜かれた橋脚に角落し用の溝を設ける。近年の周辺整備により，良好な散策路の一部として町民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001903"},{"id":"00010420","register_sub_id":"101","register_pk":"199381","name":"江連用水旧溝宮裏両樋","kana":"えづれようすいきゅうこうみやうらりょうひ","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県下妻市本宗道","lat":36.1598306,"lng":139.96718941,"geo_status":"db","era":"明治33／平成13改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"東樋門 煉瓦造2連樋門、長さ3.6m 西樋門 煉瓦造2連樋門、長さ3.6m 擁壁付","structure_material":"東樋門 煉瓦造2連樋門","registered":"2015.03.26(平成27.03.26)","register_no":"08 － 0271","desc":"鬼怒川から引いた江連用水の旧分水施設。延長三・六メートルの二連煉瓦造樋門二基と湾曲する煉瓦擁壁を一体的に築く。堰柱は上流側に水切を付け、下流側を階段状とする特徴的な形式。明治期北関東に多数建設された煉瓦樋門の一つで用水施設の近代化を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010420"},{"id":"00012099","register_sub_id":"101","register_pk":"352898","name":"旧西廣家住宅（治郎吉）缶詰工場","kana":"きゅうにしびろけじゅうたく（じろきち）かんづめこうじょう","category":"産業1次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県銚子市川口町一丁目6271","lat":35.73697,"lng":140.853935,"geo_status":"db","era":"昭和初期／昭和10年増築、昭和30年・平成21年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋一部2階建、瓦葺、建築面積343㎡","structure_material":"木造平屋一部2階建","registered":"2018.03.27(平成30.03.27)","register_no":"12-244","desc":"主屋の北に建つ。東寄りの二階建部分と、西寄りの工場部分からなり、数次にわたって増築されている。二階建部分の一階は土間で工場と連続し、二階には事務室、座敷などを配する。工場部分は木造トラスの大空間とする。漁業で栄えた銚子の歴史を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012099"},{"id":"00012098","register_sub_id":"101","register_pk":"352897","name":"旧西廣家住宅（治郎吉）主屋","kana":"きゅうにしびろけじゅうたく（じろきち）しゅおく","category":"産業1次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県銚子市川口町一丁目6271","lat":35.736859,"lng":140.85391,"geo_status":"db","era":"明治10年頃／昭和12年増築","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積193㎡","structure_material":"木造平屋一部2階建","registered":"2018.03.27(平成30.03.27)","register_no":"12-243","desc":"銚子を代表する船主の住居及び作業場。平屋建の「本館」の背後に、増築部分である「総檜」と洋館が取り付く。豪壮な商家である本館と、付書院に犬吠埼の風景をあしらうなど細部意匠を凝らす増築部分が対照的で、近代の大規模商家の有り様を良く示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012098"},{"id":"00012100","register_sub_id":"101","register_pk":"352899","name":"旧西廣家住宅（治郎吉）倉庫（北倉）","kana":"きゅうにしびろけじゅうたく（じろきち）そうこ（きたぐら）","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県銚子市川口町一丁目6271","lat":35.736915,"lng":140.854601,"geo_status":"db","era":"慶応年間(1865-1867)","year":1866,"year_source":"estimated","year_min":1865,"year_max":1867,"year_label":"慶応年間(1865-1867)","structure":"木造平屋一部2階建、瓦葺、建築面積95㎡","structure_material":"木造平屋一部2階建","registered":"2018.03.27(平成30.03.27)","register_no":"12-245","desc":"敷地東方の一段高い位置に西面して建つ。中心の切妻造平入二階建部分の正側面三方に深く下屋を延ばす構成で、壁は竪板張、屋根は桟瓦葺とする。正面中央に扉口を開き、二階南妻面に窓を開くほかは閉鎖的な構成。漁業の歴史を今に伝える特徴的な漁網倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012100"},{"id":"00012101","register_sub_id":"101","register_pk":"352900","name":"旧西廣家住宅（治郎吉）倉庫（南倉）","kana":"きゅうにしびろけじゅうたく（じろきち）そうこ（みなみぐら）","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県銚子市川口町一丁目6271","lat":35.736791,"lng":140.85459,"geo_status":"db","era":"慶応年間(1865-1867)","year":1866,"year_source":"estimated","year_min":1865,"year_max":1867,"year_label":"慶応年間(1865-1867)","structure":"木造平屋一部2階建、瓦葺、建築面積59㎡","structure_material":"木造平屋一部2階建","registered":"2018.03.27(平成30.03.27)","register_no":"12-246","desc":"敷地東方の一段高い位置に北倉と並んで建つ。中心の切妻造平入二階建部分の正側面三方に深く下屋を延ばす構成は北倉と同一であるが、やや規模が小さい。二階妻面には開口部を設けず、一階南面に窓を設ける。地域の漁業の歴史を今に伝える特徴的な漁網倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012101"},{"id":"00012102","register_sub_id":"101","register_pk":"352901","name":"旧西廣家住宅（治郎吉）煉瓦塀","kana":"きゅうにしびろけじゅうたく（じろきち）れんがべい","category":"産業1次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県銚子市川口町一丁目6271","lat":35.736803,"lng":140.853716,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"煉瓦造及び石造、延長34m","structure_material":"煉瓦造及び石造","registered":"2018.03.27(平成30.03.27)","register_no":"12-247","desc":"主屋南側の庭を画す煉瓦塀。折曲がり延長三四・五メートルで、基部に大谷石と銚子石三段を積み、上部に煉瓦をイギリス積とし、頂部は持送り状に幅を広くとって小屋根状に積む。港町銚子の歴史的景観を形成する煉瓦塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012102"},{"id":"00002608","register_sub_id":"101","register_pk":"103598","name":"旧水田家住宅長屋門","kana":"きゅうみずたけじゅうたくながやもん","category":"産業1次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県鴨川市西339","lat":35.09901688,"lng":140.00318462,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積111㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"12 － 0043","desc":"主屋の南東，道路から高い位置に建つ。桁行９間，梁間３間規模，寄棟造，桟瓦葺，出桁造の長屋門であるが，全体的に木太く，門右１室と左２室を牛小屋とする点に特徴がある。江戸時代以来の酪農地である嶺岡牧の歴史を伝える建造物として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002608"},{"id":"00000526","register_sub_id":"101","register_pk":"101516","name":"二ヶ領用水久地円筒分水","kana":"にかりょうようすいくじえんとうぶんすい","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県川崎市高津区久地341","lat":35.60728065,"lng":139.60566299,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"鉄筋コンクリート造，直径16m","structure_material":"鉄筋コンクリート造","registered":"1998.04.21(平成10.04.21)","register_no":"14 － 0017","desc":"多摩川から取水した水を灌漑面積に応じて周辺耕地に分けるために建設された農業用水施設。サイホンの原理の応用により湧き上がった水を，円筒の周囲に配された４つの水路に分水する形式。この形式の施設はその後多くつくられたが，初期の事例として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000526"},{"id":"00003400","register_sub_id":"101","register_pk":"104390","name":"西野谷用水路","kana":"にしのやようすいろ","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県妙高市大字西野谷","lat":37.01473649,"lng":138.17276237,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"石造、延長49m","structure_material":"石造","registered":"2003.07.01(平成15.07.01)","register_no":"15 － 0161","desc":"万内川七号堰堤と一体的に築かれた灌漑施設。七号堰堤上流右岸側から取水し，堤体と平行に延びる水路をＬ字型に曲げ，堤体右翼部の約１ｍ幅に刳り抜かれた堤体内を導水させた石張構造物。生活上の要請を複合的に解決した，治水施設と一体化した利水施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003400"},{"id":"00013243","register_sub_id":"101","register_pk":"366232","name":"赤祖父円筒分水槽","kana":"あかそぶえんとうぶんすいそう","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"昭和中","pref":"富山県","address":"富山県南砺市川上中字寺山1-19他","lat":36.52837222,"lng":136.93713333,"geo_status":"db","era":"昭和24年","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"鉄筋コンクリート造、面積29㎡","structure_material":"鉄筋コンクリート造","registered":"2020.04.03(令和2.04.03)","register_no":"16 － 0154","desc":"小矢部川水系赤祖父川の扇頂部に位置する。直径三・四メートルの円筒分水槽で、内円筒からの越流水を外円筒で受け、仕切板で三つの用水に分水する。赤祖父溜池工事の一環として築かれ、砺波平野における戦後の稲作の発展を支えた県内最古の円筒分水槽。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013243"},{"id":"00015170","register_sub_id":"101","register_pk":"530594","name":"旧坪岩崎鰤大敷網倉庫","kana":"きゅうつぼいわさきぶりおおしきあみそうこ","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県氷見市中波字上野476-3","lat":36.95004444,"lng":137.03911389,"geo_status":"db","era":"明治43年／平成8年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積169㎡","structure_material":"土蔵造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"16 - 0171","desc":"氷見灘浦海岸の女良漁港に南面して建つ、鰤の定置網を収納した倉庫。桁行一〇間、梁間四間、戸前付の土蔵造二階建。木太い独立柱と登梁を用いて大屋根を架け、荷擦木を張詰めた内部と、鰤形を象る雪割瓦が特徴的。大敷網で繁栄した氷見鰤漁を象徴する倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015170"},{"id":"00014154","register_sub_id":"101","register_pk":"508784","name":"釈泉寺円筒分水槽","kana":"しゃくせんじえんとうぶんすいそう","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"昭和中","pref":"富山県","address":"富山県中新川郡上市町釈泉寺字向川原50-53","lat":36.68793056,"lng":137.40496111,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"鉄筋コンクリート造、面積202㎡","structure_material":"鉄筋コンクリート造","registered":"2022.02.17(令和4.02.17)","register_no":"16-0161","desc":"上市川沿岸の用水合口化に伴い、川の扇頂部に建設された、直径九・三メートルの円筒分水槽。溢流円筒頂部には円形の管理橋を設ける。〇・五一対〇・四九の高い精度で両岸の幹線水路に分水。安定した水供給により、長年の水不足を解消した戦後の農業水利施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014154"},{"id":"00004227","register_sub_id":"101","register_pk":"105217","name":"庄川合口堰堤","kana":"しょうがわごうぐちえんてい","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県砺波市金屋","lat":36.57527197,"lng":136.99593886,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"重力式鉄筋コンクリート造堰堤、堤長103m、堤高18m、取水口・ポンプ室及び魚道付","structure_material":"重力式鉄筋コンクリート造堰堤","registered":"2004.07.23(平成16.07.23)","register_no":"16 － 0071","desc":"礪波平野を貫流する庄川に点在していた用水取入堰を集約した灌漑・発電用堰堤。１０門のラジアルゲートを付けた鉄筋コンクリート造堰堤で，左岸下流に魚道，両岸上流に取水口を設ける。我国屈指の大扇状地を潤し，穀倉地帯の近代化を支える。施工間組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004227"},{"id":"00013242","register_sub_id":"101","register_pk":"366231","name":"東山円筒分水槽","kana":"ひがしやまえんとうぶんすいそう","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"昭和中","pref":"富山県","address":"富山県魚津市東山地内","lat":36.80973889,"lng":137.459975,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"鉄筋コンクリート造、面積317㎡","structure_material":"鉄筋コンクリート造","registered":"2020.04.03(令和2.04.03)","register_no":"16 － 0153","desc":"魚津市街地の東方、片貝川の扇央部に位置する。片貝川を横断するサイフォンの出口を兼ねる直径九・一メートルの円筒分水槽で、三つの用水へ分水する。片貝川沿岸用水合口事業の一環として建設されたもので、地域の水利システム近代化の歴史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013242"},{"id":"00011495","register_sub_id":"101","register_pk":"210458","name":"岩堂セギ分水口","kana":"いわどうせぎぶんすいこう","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県甲州市塩山牛奥上ノ段1520地先他","lat":35.680901,"lng":138.738605,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造、面積9.6㎡","structure_material":"鉄筋コンクリート造","registered":"2017.05.02(平成29.05.02)","register_no":"19-0090","desc":"農業用水及び生活用水を分割するための鉄筋コンクリート造円筒分水口。三重の円筒からなり、サイフォンの原理で中心の小円筒から湧き上がった水が外側の中円筒に溜まり、中円筒隔壁に一二箇所設けられた穴で三等分され大円筒を通じて三本の水路に注ぐ仕組み。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011495"},{"id":"00011491","register_sub_id":"101","register_pk":"210454","name":"旧飯野産業組合倉庫","kana":"きゅういいのさんぎょうくみあいそうこ","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県南アルプス市飯野字村東2825-6","lat":35.641595,"lng":138.46360389,"geo_status":"db","era":"昭和3年／昭和56年移築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積106㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"19-0086","desc":"旧白根町の中心地に建つ。昭和三年に組合倉庫として建てられ、昭和五六年に現在地に移築された。木造二階建、桁行八間、梁間四間の規模で、内部は上下階とも一室とする。外壁は腰海鼠壁上部漆喰塗。小屋組はトラスに方杖を付加している。近代倉庫建築の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011491"},{"id":"00000135","register_sub_id":"101","register_pk":"101125","name":"上田蚕種協業組合事務棟","kana":"うえださんしゅきょうぎょうくみあいじむとう","category":"産業1次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市常田3-300","lat":36.39479384,"lng":138.26079832,"geo_status":"db","era":"大正6頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建，瓦葺，建築面積764㎡","structure_material":"木造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"20 － 0003","desc":"大正６年に発足した前身の上田蚕種株式会社の時に建設された，木造，二階建，瓦葺のＴ字型の事務所。外観は，下見板張りを基本とし，正面は左右対称型で，２階窓にペディメントを付けた端正な意匠に仕上げる。養蚕業で栄えた地域のシンボル的な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000135"},{"id":"00008986","register_sub_id":"101","register_pk":"162346","name":"旧上高地孵化場飼育池（信州大学山岳科学総合研究所上高地ステーション観察池）","kana":"きゅうかみこうちふかじょうしいくち（しんしゅうだいがくさんがくかがくそうごうけんきゅうじょかみこうちすてーしょんかんさついけ）","category":"産業1次","subcategory":"その他工作物","type_guess":"水路・堰堤","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県松本市安曇4469-1","lat":36.25351084,"lng":137.66760079,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"石造及びコンクリート造、面積210㎡、排水路付","structure_material":"石造及びコンクリート造","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0383","desc":"梓川の上流、明神橋の東側に所在し、東西約１１ｍ南北約３．５ｍの飼育池四基と水路からなる。石造、総面積２１０㎡で、壁体は高さ１．１ｍの玉石積とする。昭和初期頃に県内各地に建設された孵化養魚施設の構造を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008986"},{"id":"00008987","register_sub_id":"101","register_pk":"162347","name":"旧上高地孵化場物置（信州大学山岳科学総合研究所上高地ステーション別館）","kana":"きゅうかみこうちふかじょうものおき（しんしゅうだいがくさんがくかがくそうごうけんきゅうじょかみこうちすてーしょんべっかん）","category":"産業1次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県松本市安曇4469-1","lat":36.253315,"lng":137.66798336,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0384","desc":"飼育池の南東に東西棟で建つ。桁行５．５ｍ梁間３．６ｍ、切妻造鉄板葺で、屋根に煙出しを上げる。外部は下見板張で、北面を出入口とし、残る三面に窓を開け、内部は中央に囲炉裏を築き、周囲を畳敷とする。孵化養魚施設の施設構成を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008987"},{"id":"00015014","register_sub_id":"101","register_pk":"529292","name":"旧佐藤家住宅（藤本）文庫蔵","kana":"きゅうさとうけ（ふじもと）じゅうたくぶんこぐら","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県上田市上塩尻字南側91","lat":36.418625,"lng":138.21584722,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"20 - 0653","desc":"敷地北西に東面して建ち、文書や家財などの収納蔵。二階建切妻造妻入、置屋根形式の桟瓦葺。壁は角材を積上げたいわゆる井籠蔵で、外壁は漆喰塗仕上とする。内部は各階一室の板敷で東に戸口と窓を設け、南東に階段を配す。敷地景観をつくる貴重な構造の蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015014"},{"id":"00015011","register_sub_id":"101","register_pk":"529289","name":"旧佐藤家住宅（藤本）一号蚕室","kana":"きゅうさとうけじゅうたく（ふじもと）いちごうさんしつ","category":"産業1次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県上田市上塩尻字南側91","lat":36.41825278,"lng":138.21594722,"geo_status":"db","era":"明治23年／昭和中期、平成12年改修","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積63㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"20 - 0650","desc":"上田市街地北西に位置する旧蚕種製造販売業の蚕室。敷地中央に建つ二階建切妻造桟瓦葺南北棟で、南面下屋上は手摺を廻らした作業場。外壁は漆喰塗仕上で軒まで塗込める。地下貯桑庫や火炉、簀子天井や開閉式換気口など残り、往事の蚕種業の様相を伝える蚕室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015011"},{"id":"00015012","register_sub_id":"101","register_pk":"529290","name":"旧佐藤家住宅（藤本）一号蚕室附属室","kana":"きゅうさとうけじゅうたく（ふじもと）いちごうさんしつふぞくしつ","category":"産業1次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県上田市上塩尻字南側91","lat":36.41834444,"lng":138.21597778,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土藏造2階建、瓦葺、建築面積23㎡","structure_material":"土藏造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"20 - 0651","desc":"一号蚕室の北に接続する蚕室。二階建切妻造桟瓦葺南北棟で北と西に庇を付す。外壁は漆喰塗仕上で軒まで塗込め腰は下見板張。一階は一室の土間で北と西に戸口、二階は一室の板敷で北と西に窓を開け、束立の和小屋を現す。一号蚕室に続き敷地景観をつくる蚕室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015012"},{"id":"00015015","register_sub_id":"101","register_pk":"529293","name":"旧佐藤家住宅（藤本）味噌蔵","kana":"きゅうさとうけじゅうたく（ふじもと）じゅうたくみそぐら","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県上田市上塩尻字南側91","lat":36.418625,"lng":138.21576944,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"20 - 0654","desc":"文庫蔵の西に東面して建つ土蔵。二階建切妻造妻入、置屋根形式の桟瓦葺。外壁は漆喰仕上。一階は一室の土間で味噌蔵、二階は一室の板敷で道具蔵。二階上部は垂木上面を簓子状とし、羽重ねに張った野地板を現す珍しいつくり。文庫蔵に続き、敷地景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015015"},{"id":"00015016","register_sub_id":"101","register_pk":"529294","name":"旧佐藤家住宅（藤本）表門","kana":"きゅうさとうけじゅうたく（ふじもと）じゅうたくもん","category":"産業1次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上田市上塩尻字南側91-3","lat":36.41831111,"lng":138.21589444,"geo_status":"db","era":"明治中期／明治37年移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口2.7m、左右袖塀付","structure_material":"木造","registered":"2024.08.15(令和6.08.15)","register_no":"20 - 0655","desc":"通りから路地で引込んだ敷地入口に南面する一間一戸の薬医門。左右に袖塀を付す。小屋組は二重梁とし、小屋束を貫で固める。控柱間の中央の梁は蛙股で受け、梁先の桁で軒を支持。軒は二軒繁垂木。全体に木柄が太く、重厚な外観で、敷地の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015016"},{"id":"00015013","register_sub_id":"101","register_pk":"529291","name":"旧佐藤家住宅（藤本）二号蚕室","kana":"きゅうさとうけじゅうたく（ふじもと）にごうさんしつ","category":"産業1次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県上田市上塩尻字南側88","lat":36.41811667,"lng":138.21591389,"geo_status":"db","era":"明治23年","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土藏造2階建、瓦葺、建築面積106㎡","structure_material":"土藏造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"20 - 0652","desc":"敷地南寄りに南面する蚕室。二階建切妻造桟瓦葺の東西棟で、棟全体に越屋根を設け、南北に下屋を付す。外壁は漆喰塗仕上で、軒を垂木形に塗込め、北と南に窓や換気口を設ける。内部は火炉、簀子天井や開閉式換気口など残し、往事の蚕種業の様相を伝える蚕室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015013"},{"id":"00014370","register_sub_id":"101","register_pk":"511359","name":"黒川堰追平隧道","kana":"くろかわせぎおいだいらずいどう","category":"産業1次","subcategory":"土木構造物","type_guess":"隧道・坑口","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県松本市波田字追平3622-4","lat":36.17950278,"lng":137.79287778,"geo_status":"db","era":"明治34年頃／大正4年・昭和12年改修","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"石造、延長37m、幅員1.2m","structure_material":"石造","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0615","desc":"梓川右岸にある農業用水路の隧道で下流の河岸段丘上を灌漑する。高さ１・３メートル、開削当初は素掘りで、大正期に石積改修し、切石積アーチ構造とした。側壁は現場の岩を利用し、アーチ部は梓川の花崗岩等を利用。コンクリート普及以前の隧道として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014370"},{"id":"00003978","register_sub_id":"101","register_pk":"104968","name":"塩原家住宅蚕屋","kana":"しおはらけじゅうたくさんや","category":"産業1次","subcategory":"建築物","type_guess":"厩舎","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市今井上耕地5990","lat":36.1507118,"lng":137.89008855,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積131㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"20 － 0178","desc":"主屋の背面側に建つ。木造２階建，切妻造，鉄板葺，平入で，間口１０間の長大な規模を持つ。正面側には全長に渡って桟瓦葺の下屋を設ける。全体にたちが高く，開口部の少ない特異な外観で，養蚕で栄えた豪農の住宅景観を今日に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003978"},{"id":"00005871","register_sub_id":"101","register_pk":"106857","name":"花屋ホテル水車小屋","kana":"はなやほてるすいしゃごや","category":"産業1次","subcategory":"建築物","type_guess":"厩舎","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県上田市別所温泉169","lat":36.350975,"lng":138.159332,"geo_status":"db","era":"明治前期／昭和56移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、茅葺、建築面積6.8㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0288","desc":"大浴室の西側に建ち，ほぼ１間半四方の規模で，木造平屋建，寄棟造，茅葺とする。西側に水車を付け，西壁を下見板張としている。北側に下地窓を開き，南側に出入口を設ける。柱は栗材で水に強い構造をもつ。渡廊下の脇に建ち，のどかな田園風の景観を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005871"},{"id":"00009168","register_sub_id":"101","register_pk":"164721","name":"松川村収蔵庫","kana":"まつかわむらしゅうぞうこ","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県北安曇郡松川村7019-98他","lat":36.42512731,"lng":137.86074248,"geo_status":"db","era":"昭和14年頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積417㎡","structure_material":"土蔵造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地北端に建つ。桁行36.4メートル梁間9.1メートル、土蔵造、切妻造、置屋根式セメント瓦葺で、蔵前を附属する。漆喰塗の外壁に小窓を連ね、腰高に下見板を張る。内壁に荷摺木を配り、小屋はキングポストトラス組。県中部で希少な戦前の大型穀物倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009168"},{"id":"00005151","register_sub_id":"101","register_pk":"106141","name":"山岸家住宅旧牛乳処理場","kana":"やまぎしけじゅうたくきゅうぎゅうにゅうしょりじょう","category":"産業1次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県長野市松代町松代1220","lat":36.559517,"lng":138.203865,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0219","desc":"敷地の西寄りにある。東面して建つ南北棟の切妻造，平屋建，桟瓦葺で，両側面に下屋を設ける。内部は警視庁令「牛乳営業取締規則」に則った平面構成になる。大棟中央に設けた換気のための越屋根が牛乳処理場らしい外観を特徴づけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005151"},{"id":"00014241","register_sub_id":"101","register_pk":"509631","name":"与良町郷蔵","kana":"よらまちごうぐら","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県小諸市与良町二丁目2637","lat":36.324225,"lng":138.43148056,"geo_status":"db","era":"江戸末期／明治中期・昭和57年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積66㎡","structure_material":"土蔵造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"20 - 0602","desc":"小諸城下の長勝寺境内に所在する郷蔵。土蔵造二階建切妻造平入で、桟瓦葺の置屋根形式。外壁は荒壁仕上げとし、北に下屋を付して二個所の戸口を開く。内部は一・二階とも二室に仕切る。城下で藩政時代に遡る唯一の郷蔵で、近代以降も集会所として活躍する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014241"},{"id":"00009458","register_sub_id":"101","register_pk":"194251","name":"旧和良森林組合事務所","kana":"きゅうわらしんりんくみあいじむしょ","category":"産業1次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和中","pref":"岐阜県","address":"岐阜県郡上市和良町沢字堂ノ前1027-1他","lat":35.74959085,"lng":137.08646728,"geo_status":"db","era":"昭和26年／昭和37年移築","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造2階建、瓦葺、建築面積85㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"21 － 0207","desc":"通り沿いに建つ。木造二階建、妻入、建築面積八五平方メートル、切妻造桟瓦葺で正面を半切妻とする。外壁は横板張ペンキ塗で小庇を廻らせる。下階はカウンターを設けた事務室として上階に和室を配し、小屋は洋小屋を組む。和良の近代化を示す洋風の事務所建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009458"},{"id":"00001775","register_sub_id":"101","register_pk":"102765","name":"大井上康学術文献資料館（旧大井上理農学研究所事務所及び実験所）","kana":"おおいのうえやすしがくじゅつぶんけんしりょうかん（きゅうおおいのうえりのうがくけんきゅうしょじむしょおよびじっけんしょ）","category":"産業1次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県伊豆市上白岩2000","lat":34.95882479,"lng":138.97588782,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"22 － 0069","desc":"理学者大井上康が，葡萄研究所として自ら設計した木造，鉄板瓦棒葺，平屋建の洋風建築。正面に，方杖に支えられた玄関ポーチと上げ下げ窓を配し，外装を主として下見板張とする瀟洒な建物。品種改良の末，ここで初めて「巨峰」が栽培されたと云われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001775"},{"id":"00009966","register_sub_id":"101","register_pk":"196113","name":"菊川赤れんが倉庫","kana":"きくがわあかれんがそうこ","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県菊川市堀之内字古井戸1425","lat":34.75991289,"lng":138.08514753,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造2階建、瓦葺、建築面積79㎡","structure_material":"煉瓦造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"22 － 0194","desc":"菊川駅南側に南北棟で建ち、煉瓦造二階建、寄棟造桟瓦葺で、小屋は洋小屋を組む。外壁下部や軒蛇腹、開口部の欠円アーチなどに焼過煉瓦を効果的に用いる。茶葉の搬出入を考慮して開口を配置し、内部に合組作業の用具痕跡を残すなど、菊川製茶の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009966"},{"id":"00002417","register_sub_id":"101","register_pk":"103407","name":"築留二番樋","kana":"つきどめにばんひ","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府柏原市上市2-320","lat":34.58289011,"lng":135.62503562,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"煉瓦造単アーチ樋門、長さ55m、幅2m","structure_material":"煉瓦造単アーチ樋門","registered":"2001.10.12(平成13.10.12)","register_no":"27 － 0142","desc":"市中心部，長瀬川が大和川から分派する地点に築かれる。坑口は，直径約１．６ｍの３枚厚の半円アーチからなる馬蹄形断面で，坑門とそこから斜めに張り出す翼壁上部に花崗岩の笠石を載せる。小規模ながら，明治の近代河川景観の様を今に伝える貴重な構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002417"},{"id":"00005351","register_sub_id":"101","register_pk":"106339","name":"小田井灌漑用水路木積川渡井","kana":"おだいかんがいようすいろこずみがわとい","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県紀の川市西三谷地内","lat":34.2771721,"lng":135.33483417,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"煉瓦造単アーチ橋、橋長6.0m、幅員3.8m","structure_material":"煉瓦造単アーチ橋","registered":"2006.03.02(平成18.03.02)","register_no":"30 － 0085","desc":"打田町の町境を流れる木積川に架かる水路橋。橋長６．０ｍの煉瓦造単アーチ橋で，アーチは煉瓦４枚厚とし，イギリス積で築かれたスパンドレル中央には橋名等を陰刻した銘板を嵌め込む。側面頂部の水平帯にはデンティルと鋸歯飾りをあしらう丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005351"},{"id":"00005353","register_sub_id":"101","register_pk":"106341","name":"小田井灌漑用水路小庭谷川渡井","kana":"おだいかんがいようすいろこにわだにがわとい","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県伊都郡かつらぎ町笠田東","lat":34.29193233,"lng":135.47564649,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"煉瓦造単アーチ橋、橋長9.3m、幅員7.4m","structure_material":"煉瓦造単アーチ橋","registered":"2006.03.02(平成18.03.02)","register_no":"30 － 0087","desc":"紀ノ川に右岸から合流する堂田川に架かる水路橋。橋長９．３ｍの煉瓦造単アーチ橋で，石積の基部から煉瓦４枚厚のアーチを立ち上げ，スパンドレルはフランス積で築く。明治末期に着手された用水路改修工事の関連施設の中で，最初期に竣工した構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005353"},{"id":"00005352","register_sub_id":"101","register_pk":"106340","name":"小田井灌漑用水路龍之渡井","kana":"おだいかんがいようすいろたつのとい","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県紀の川市西野山～伊都郡かつらぎ町高田","lat":34.28307904,"lng":135.44828354,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造・石造及びコンクリート造単アーチ橋、橋長21m、幅員5.3m","structure_material":"煉瓦造・石造及びコンクリート造単アーチ橋","registered":"2006.03.02(平成18.03.02)","register_no":"30 － 0086","desc":"那賀町とかつらぎ町の境を流れる穴伏川に架かる水路橋。橋長２１ｍの大規模な煉瓦造単アーチ橋で，煉瓦７枚厚のアーチは段状に迫り出したつくりで，スパンドレルを石積で築き，その上部にフランス積の煉瓦壁を立ち上げる独特の構造形式とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005352"},{"id":"00005354","register_sub_id":"101","register_pk":"106342","name":"小田井灌漑用水路中谷川水門","kana":"おだいかんがいようすいろなかたにがわすいもん","category":"産業1次","subcategory":"土木構造物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県伊都郡かつらぎ町中飯降","lat":34.30351932,"lng":135.53467403,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"煉瓦造、延長13m、幅員6.4m","structure_material":"煉瓦造","registered":"2006.03.02(平成18.03.02)","register_no":"30 － 0088","desc":"紀ノ川にほぼ平行して流れる用水路が中谷川と交差する地点に築かれた暗渠。サイホンの原理を利用し川の下に築かれる。アーチは煉瓦造４枚厚で，壁面をフランス積とし，頂部にはパラペットを立ち上げる。藩政時代に開削された大規模灌漑用水路の近代化を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005354"},{"id":"00014403","register_sub_id":"101","register_pk":"511392","name":"旧東山東農業協同組合事務所","kana":"きゅうひがしさんどうのうぎょうきょうどうくみあいじむしょ","category":"産業1次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県和歌山市山東中字川南54-4","lat":34.20329167,"lng":135.25995,"geo_status":"db","era":"昭和23年／同４０年・令和３年改修","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造2階建、瓦葺、建築面積77㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"30 - 0328","desc":"市南東部田園地帯の集落に所在する農業の組合事務所。二階建、半切妻造妻入、外壁下見板張で軒際漆喰仕上、正面頂部ガラリと二階の二連窓が特徴的。側面に添え柱を付す。一階は事務室、二階に広間と電話交換室や放送室等を配し、農村の賑わいを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014403"},{"id":"00008752","register_sub_id":"101","register_pk":"149473","name":"太地水産共同組合事務所","kana":"たいじすいさんきょうどうくみあいじむしょ","category":"産業1次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県東牟婁郡太地町大字太地字寄子路3263-2","lat":33.59126872,"lng":135.94503267,"geo_status":"db","era":"大正7年","year":1918,"year_source":"converted","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"30 － 0144","desc":"太地漁港近く、通りに西面して建つ。桁行11ｍ梁間9.5ｍの木造、入母屋造桟瓦葺で周囲に庇をまわす。正面中央に玄関を設け、北側に台所、南に事務室、東背面に和室などを配する。外部木部は建具を含め、淡いピンク色のペンキが塗られ、特異な外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008752"},{"id":"00016438","register_sub_id":"101","register_pk":"536505","name":"奥田家住宅牛小屋","kana":"おくだけじゅうたくうしごや","category":"産業1次","subcategory":"建築物","type_guess":"厩舎","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県安芸高田市向原町坂字隠地6141-1他","lat":34.607375,"lng":132.73114722,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"34 - 0327","desc":"敷地の東側に位置する牛小屋。西面して建つ平屋建切妻造平入桟瓦葺で、西面中央は外壁を東に後退して設け、正面側を吹放ちとする。内部は土間で６室に間仕切り、南側は作業場、北側は倉庫や牛小屋で上部に物置を設ける。豪農の生業を伝える桁行長大な牛小屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016438"},{"id":"00016436","register_sub_id":"101","register_pk":"536503","name":"奥田家住宅主屋","kana":"おくだけじゅうたくおもや","category":"産業1次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県安芸高田市向原町坂字隠地6141-1他","lat":34.60733333,"lng":132.73092222,"geo_status":"db","era":"明治17年／昭和30年代・同57年頃改修","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造2階建、瓦葺、建築面積299㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"34 - 0325","desc":"市域南東端の山間に位置する旧家の主屋。敷地中央に南面する２階建片入母屋造平入桟瓦葺で、内部の東は広大な土間で、西は２列８室を配す。南西の主座敷は床脇に五段の違棚を飾り、部屋境の欄間彫刻など凝ったつくり。地域の豪農らしい大規模で良質な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016436"},{"id":"00016439","register_sub_id":"101","register_pk":"536506","name":"奥田家住宅木小屋","kana":"おくだけじゅうたくきごや","category":"産業1次","subcategory":"建築物","type_guess":"厩舎","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県安芸高田市向原町坂字隠地6141-1他","lat":34.60749167,"lng":132.73104444,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"34 - 0328","desc":"敷地の北東隅に位置する木小屋。南面して建つ平屋建切妻造平入桟瓦葺で、外壁中塗仕上とする。内部は土間で、中央に一間幅の通路を設け、東・西脇間に各一室を配し、南・東面を吹放ちとする。小屋は登梁形式。牛小屋と連なり豪農の屋敷景観を伝える木小屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016439"},{"id":"00016437","register_sub_id":"101","register_pk":"536504","name":"奥田家住宅土蔵","kana":"おくだけじゅうたくどぞう","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県安芸高田市向原町坂字隠地6141-1他","lat":34.60720278,"lng":132.73115556,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積74㎡","structure_material":"土蔵造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"34 - 0326","desc":"敷地南東隅に位置する家財蔵。二階建切妻造平入桟瓦葺で、西に戸口を設けて下屋を付し、蔵前とする。外壁は漆喰塗仕上で軒まで塗込め、三段の水切を廻らし、腰をモルタル洗出仕上。各階板敷の一室で、小屋組は登梁形式。敷地南東の景観をつくる重厚な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016437"},{"id":"00016440","register_sub_id":"101","register_pk":"536507","name":"奥田家住宅門","kana":"おくだけじゅうたくもん","category":"産業1次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県安芸高田市向原町坂字隠地6141-1","lat":34.607175,"lng":132.73097222,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"34 - 0329","desc":"敷地南面に開く一間一戸の薬医門で東脇に潜戸を設ける。軸部は角柱の本柱と控柱を腰貫、飛貫で固め、男梁先端の舟肘木で軒桁を受ける。軒は一軒疎垂木で化粧屋根裏とし、屋根は切妻造桟瓦葺。乳金物など打った板戸を開き、豪農屋敷の風格ある表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016440"},{"id":"00001646","register_sub_id":"101","register_pk":"102636","name":"中の峠隧道","kana":"なかのたおずいどう","category":"産業1次","subcategory":"土木構造物","type_guess":"隧道・坑口","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市西条町郷曽字柏原中の峠","lat":34.37751187,"lng":132.68610119,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造アーチ坑口、全長327m","structure_material":"鉄筋コンクリート造アーチ坑口","registered":"2000.04.28(平成12.04.28)","register_no":"34 － 0024","desc":"昭和元年の渇水を契機に，小田山川と深道池間に建設された農業用水路の一部。全長327ｍ。当初建設された径間長約0.7ｍのＲＣ造欠円アーチからなる南坑口に，落盤防止のため昭和18年長さ約3.8ｍのＲＣ造箱形坑道を延長する。設計施工は地元の沖田嘉市。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001646"},{"id":"00000708","register_sub_id":"101","register_pk":"101698","name":"三永の石門","kana":"みながのいしもん","category":"産業1次","subcategory":"土木構造物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条町上三永字上泓710-1","lat":34.40051513,"lng":132.80302299,"geo_status":"db","era":"明治15頃","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"石造アーチ橋，幅11.7m，アーチ部幅員3.7m，長さ9.6m","structure_material":"石造アーチ橋","registered":"1998.09.02(平成10.09.02)","register_no":"34 － 0017","desc":"旧国道２号線の開削工事に伴い分断される既設の農業用水路を確保するため，架けられた石造アーチ型の水路兼歩道橋で，明治１５年頃竣工したと伝える。切石で組み上げたアーチ部の周囲を薄い板石で巻く独特の工法になる。昭和５３年に近隣に移築保存された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000708"},{"id":"00002440","register_sub_id":"101","register_pk":"103430","name":"江畑溜池堰堤","kana":"えばたためいけえんてい","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県山口市阿知須源河","lat":34.02366259,"lng":131.31660608,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"コンクリート造重力式堰堤、堤長69m、堤高14m","structure_material":"コンクリート造重力式堰堤","registered":"2001.10.12(平成13.10.12)","register_no":"35 － 0041","desc":"町東部にある農業水利施設。堤体表面に花崗岩を張る堤長６９ｍ，堤高１４ｍの中央越流式堰堤で，越流部脇に半円形平面の取水塔を設ける。県技師武冨憲時，同技手荒瀬長一を中心に建設され，コンクリート造重力式溜池堰堤として最初期のもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002440"},{"id":"00000367","register_sub_id":"101","register_pk":"101357","name":"沖ノ山電車竪坑石垣","kana":"おきのやまでんしゃたてこういしがき","category":"産業1次","subcategory":"その他工作物","type_guess":"隧道・坑口","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県宇部市大字小串字沖ノ山1980","lat":33.95461915,"lng":131.22893569,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"石造，高さ3.5m，延長72.4m","structure_material":"石造","registered":"1997.11.05(平成9.11.05)","register_no":"35 － 0008","desc":"海底炭田採掘を目的に建設された炭鉱施設で，その名は昭和３２年に接続してつくられた電車坑道に由来する。石垣は竪坑櫓の基礎として建設されたもので，工業都市として栄えた宇部市に現存する数少ない初期の産業遺産である。櫓は昭和３９年改修時のもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000367"},{"id":"00009536","register_sub_id":"101","register_pk":"194329","name":"蜂谷ビル（旧東洋捕鯨株式会社下関支店）","kana":"はちやびる（きゅうとうようほげいかぶしきがいしゃしものせきしてん）","category":"産業1次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山口県","address":"山口県下関市岬之町3-21他","lat":33.95165844,"lng":130.9351361,"geo_status":"db","era":"大正15年／昭和43年増築","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"煉瓦造及び鉄筋コンクリート造2階建一部地階付、建築面積234㎡","structure_material":"煉瓦造及び鉄筋コンクリート造2階建一部地階付","registered":"2013.03.29(平成25.03.29)","register_no":"35 － 0072","desc":"関門海峡に突き出す岬上に建つ。煉瓦造二階建の北に鉄筋コンクリート造二階建を増築。煉瓦造部の外壁はモルタル仕上で、二階通しの柱形頂部に幾何学形態の装飾を付す。窓間の方立はタイル貼。内部は改修されるが後補天井上に当初の天井中心飾等が残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009536"},{"id":"00009380","register_sub_id":"101","register_pk":"194173","name":"三田尻塩田旧越中屋釜屋煙突","kana":"みたじりえんでんきゅうえっちゅうやかまやえんとつ","category":"産業1次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県防府市大字浜方字鶴浜381-3","lat":34.01727686,"lng":131.55976597,"geo_status":"db","era":"大正前期／平成2年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"石造、高さ13.2m、煙道付","structure_material":"石造","registered":"2012.08.13(平成24.08.13)","register_no":"35 － 0070","desc":"三田尻塩田記念産業公園の西辺南寄りに建つ。石造、基部直径二･四メートル総高一三･二メートル、北東に幅一･五メートル長二･五メートルの煙道が附属する。塩田から採取した鹹水を煮詰める施設の一部で、昭和三〇年代まで盛んだった製塩業の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009380"},{"id":"00013192","register_sub_id":"101","register_pk":"368416","name":"中村家住宅刻み煙草工場","kana":"なかむらけじゅうたくきざみたばここうじょう","category":"産業1次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市池田町マチ2265他","lat":34.02908333,"lng":133.81187778,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"36 － 0200","desc":"敷地北端に南面して建つ。木造二階建、切妻造桟瓦葺で、煙草の刻み工場と伝わる。一階は三室に分かれ、中央を広くとり、床は中央の部屋の西半と東の部屋の北半を板張とし、その他は土間とする。二階は一室で和小屋組を現す。刻み煙草工場の構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013192"},{"id":"00013191","register_sub_id":"101","register_pk":"368415","name":"中村家住宅主屋","kana":"なかむらけじゅうたくしゅおく","category":"産業1次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市池田町マチ2265","lat":34.02886389,"lng":133.81188333,"geo_status":"db","era":"明治24年","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建、瓦葺、建築面積237㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"36 － 0199","desc":"池田町の中通りに南面して建つ、刻み煙草の商家の主屋。間口１５・９メートルの木造二階建、切妻造桟瓦葺で、両側に本瓦葺の袖卯建を上げる。内部は通り土間沿いに洋風の応接間を配し、廊下を介し四間取の座敷と繋ぐ。刻み煙草で栄えた池田の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013191"},{"id":"00004423","register_sub_id":"101","register_pk":"105413","name":"船本家牧舎（旧富田畜産部牧舎）","kana":"ふなもとけぼくしゃ（きゅうとみたちくさんぶぼくしゃ）","category":"産業1次","subcategory":"建築物","type_guess":"厩舎","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県鳴門市大麻町桧字野神ノ北40","lat":34.15612169,"lng":134.49563925,"geo_status":"db","era":"大正6／大正8増築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造及び煉瓦造2階建、瓦葺、建築面積246㎡","structure_material":"木造及び煉瓦造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"36 － 0047","desc":"南西隅を突出したＬ字型平面の建物で，西半が大正６年，東半が同８年の増築である。１階煉瓦造，２階真壁造の混構造になり，トラス小屋組で桟瓦葺屋根を架ける。牛などの牧舎用途の他，食品加工も行われた。ドイツ人の設計・施工になるという稀少な農業施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004423"},{"id":"00000712","register_sub_id":"101","register_pk":"101702","name":"観音寺市郷土資料館展示館（旧三豊郡農会農事試験場）","kana":"かんのんじしきょうどしりょうかんてんじかん（きゅうみとよぐんのうかいのうじしけんじょう）","category":"産業1次","subcategory":"建築物","type_guess":"資料館","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県観音寺市有明町3-55","lat":34.13084405,"lng":133.64348266,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建渡り廊下付属，瓦葺，建築面積146㎡","structure_material":"木造平屋建渡り廊下付属","registered":"1998.09.02(平成10.09.02)","register_no":"37 － 0016","desc":"本館の背後に建ち，渡廊下で本館と結ばれる。寄棟屋根の中央に立ち上げた明かり取り用の腰屋根とその架構に特徴がある。内部は一室空間で，洋風トラスの小屋組を露出する。腰屋根部小屋組の梁下の方杖に反曲材を用いてアクセントをつけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000712"},{"id":"00000711","register_sub_id":"101","register_pk":"101701","name":"観音寺市郷土資料館本館（旧三豊郡農会農事試験場）","kana":"かんのんじしきょうどしりょうかんほんかん（きゅうみとよぐんのうかいのうじしけんじょう）","category":"産業1次","subcategory":"建築物","type_guess":"資料館","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県観音寺市有明町3-35","lat":34.13086589,"lng":133.64368244,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造２階建，瓦葺，建築面積108㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"37 － 0015","desc":"木造２階建，寄棟造，桟瓦葺の洋館。左右対称のデザインで，玄関ポーチの左右に階下階上とも２連の上げ下げ窓を配し，階上中央の窓上部に切妻の破風をつけ，その内部をティンバーワークで飾っている。洋風建築の普及と消化を示す好個の事例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000711"},{"id":"00007596","register_sub_id":"101","register_pk":"108578","name":"旧仲枡塩田水門","kana":"きゅうなかますえんでんすいもん","category":"産業1次","subcategory":"土木構造物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県綾歌郡宇多津町浜一番丁4","lat":34.31315769,"lng":133.80772472,"geo_status":"db","era":"大正15／昭和62移設","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"石造水門、幅3.8m、高さ5.3m","structure_material":"石造水門","registered":"2009.01.08(平成21.01.08)","register_no":"37 － 0322","desc":"町西部、瀬戸内海に臨む旧入浜式塩田敷地内に所在する。塩田からの余水の排出用に作られた、１．５ｍスパン２門よりなる高さ５．３ｍの水門。長大な花崗岩の柱と梁を組み合わせて築いた大規模な塩田水門で、近代における宇多津塩田の発展の歴史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007596"},{"id":"00008595","register_sub_id":"101","register_pk":"134991","name":"こめっせ宇多津（旧宇多津町農業協同組合倉庫）","kana":"こめっせうたづ（きゅううたづちょうのうぎょうきょうどうくみあいそうこ）","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町1882-3","lat":34.31021317,"lng":133.8248488,"geo_status":"db","era":"昭和11年／平成20年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"37 － 0369","desc":"町役場の西に道路を挟んで敷地を占める。東西棟の切妻造桟瓦葺で、南面全面に下屋を付設。桁行一五メートル梁間七・六メートル、下屋奥行二・九メートルの大規模な倉庫で、平屋建ながら、棟高が八メートルを越える。宇多津の繁栄を伝える建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008595"},{"id":"00001537","register_sub_id":"101","register_pk":"102527","name":"満濃池樋門","kana":"まんのういけひもん","category":"産業1次","subcategory":"土木構造物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県仲多度郡まんのう町神野字神野45-4","lat":34.16453674,"lng":133.86536195,"geo_status":"db","era":"明治3／昭和3･26改築","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"石造、間口3.5m、高さ4.2m、袖壁付き、底樋管延長197m附属","structure_material":"石造","registered":"2000.02.15(平成12.02.15)","register_no":"37 － 0026","desc":"弥勒石穴建設で信望を得た軒原庄蔵が安政の地震で決壊した満濃池堰堤下の石樋に代えて建設するに始まる全長１９７ｍの底樋隧道とその出口。坑口周りに五角形迫石を用い、石造のコーニス，袖壁、柱頭付端柱とで坑門を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001537"},{"id":"00001536","register_sub_id":"101","register_pk":"102526","name":"弥勒石穴","kana":"みろくせっけつ","category":"産業1次","subcategory":"土木構造物","type_guess":"隧道・坑口","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県さぬき市大川町富田中3519-1地先","lat":34.25134024,"lng":134.24512849,"geo_status":"db","era":"安政4","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"石造坑口、延長189m","structure_material":"石造坑口","registered":"2000.02.15(平成12.02.15)","register_no":"37 － 0025","desc":"弥勒池貯水量増加のために建設された導水路の一部で，三ツ石山の岩盤を穿って掘られた延長１８９ｍの隧道。坑口は石材と石積擁壁で保護されている。地元の数学者萩原栄次郎の協力を得て，庄屋軒原庄蔵が設計，多田信蔵が工事監督を担当したとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001536"},{"id":"00003153","register_sub_id":"101","register_pk":"104143","name":"井口四番浜北丸樋","kana":"いぐちよんばんはまきたまるひ","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県今治市上浦町井口の海岸","lat":34.26486324,"lng":133.04251694,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、延長7.8m","structure_material":"石造","registered":"2003.01.31(平成15.01.31)","register_no":"38 － 0030","desc":"井口四番浜の北側，堤防が海岸線から内陸側に折曲る一辺に設けられる。半円状に張り出した延長７．８ｍの花崗岩造の建造物で，ほぼ垂直の壁面を谷積状に築く。塩田東側の他２基に比べて小規模で樋自体は改造されているが，現在も排水機能を果たす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003153"},{"id":"00003152","register_sub_id":"101","register_pk":"104142","name":"井口四番浜南丸樋","kana":"いぐちよんばんはまみなみまるひ","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県今治市上浦町井口の海岸","lat":34.26447207,"lng":133.04347294,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、延長12m","structure_material":"石造","registered":"2003.01.31(平成15.01.31)","register_no":"38 － 0029","desc":"井口三番浜丸樋の北側に位置する。花崗岩を用いた延長１２ｍ，上幅０．９ｍの空積構造物。法勾配をもたせた下部を谷積状に積み，ほぼ垂直に積んだ上部を布積風に築く。当地における江戸から近代の塩業の繁栄を支えた基盤施設で，現在では類例の少ない建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003152"},{"id":"00001145","register_sub_id":"101","register_pk":"102135","name":"愛媛蚕種株式会社事務室・玄関","kana":"えひめさんしゅかぶしきがいしゃじむしつ・げんかん","category":"産業1次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛媛県","address":"愛媛県八幡浜市保内町川之石3-70","lat":33.47726797,"lng":132.39494397,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造２階建，鉄板葺一部スレート葺，建築面積209㎡","structure_material":"木造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"38 － 0004","desc":"町内の呉服商兵頭寅一郎が開始した蚕種製造「日進館」の事務所建築。南北に長い敷地の南東に位置し、南東端隅切部に玄関を設け、北方に蚕室棟を接続させる。木造モルタル塗の洋館で、階下の窓上に三角ペジメントをつけ、玄関上部に浅いポーチを張りだす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001145"},{"id":"00001146","register_sub_id":"101","register_pk":"102136","name":"愛媛蚕種株式会社第１蚕室","kana":"えひめさんしゅかぶしきがいしゃだいいちさんしつ","category":"産業1次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県八幡浜市保内町川之石3-70","lat":33.47741662,"lng":132.3949384,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造３階建，瓦葺，建築面積210㎡","structure_material":"木造３階建","registered":"1999.06.07(平成11.06.07)","register_no":"38 － 0005","desc":"事務室・玄関棟の北方に延びる木造３階建、南北棟の蚕室棟。小屋組はがっしりしたキングポストトラスによる。各階共西側に廊下をとり、街路沿いの東面には板戸を全長に亘って建て込み、その上部桁下までをガラス窓とする特徴的な外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001146"},{"id":"00001147","register_sub_id":"101","register_pk":"102137","name":"愛媛蚕種株式会社第２蚕室","kana":"えひめさんしゅかぶしきがいしゃだいにさんしつ","category":"産業1次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県八幡浜市保内町川之石3-70","lat":33.47752439,"lng":132.39470057,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造２階建，瓦葺，建築面積210㎡","structure_material":"木造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"38 － 0006","desc":"第１蚕室の北方に続く蚕室棟。第１蚕室より１階分高い地盤に建つことから２階建となる。第１蚕室とは煉瓦造防火壁を建ち上げて境とし、第１蚕室とともに東側坂道沿いに独特の景観をつくる。地域の産業発展の過程を示すものとしても貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001147"},{"id":"00003151","register_sub_id":"101","register_pk":"104141","name":"旧井口三番浜丸樋","kana":"きゅういぐちさんばんはままるひ","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県今治市上浦町井口の海岸","lat":34.26350552,"lng":133.04409188,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、延長8.5m","structure_material":"石造","registered":"2003.01.31(平成15.01.31)","register_no":"38 － 0028","desc":"芸予諸島大三島の東岸に位置する塩田施設の，海岸線と塩田跡が接する堤防沿いに築かれた石積建造物。塩田の余水排出を主な目的として築かれ，その外側を半円状に張り出した延長８．５ｍの石造壁が，海水の出を確保しつつ風浪による樋の損傷を防ぐ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003151"},{"id":"00007812","register_sub_id":"101","register_pk":"108793","name":"旧山根製錬所煙突","kana":"きゅうやまねせいれんじょえんとつ","category":"産業1次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県新居浜市角野新田町3-2822-1","lat":33.9204149,"lng":133.3100143,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"煉瓦造、高さ19m","structure_material":"煉瓦造","registered":"2009.08.07(平成21.08.07)","register_no":"38-0093","desc":"山根競技場の南側に位置する生子山の頂上に建つ。低品位鉱の有効利用を図るために築かれた製錬所施設の一部。高さ１９ｍ、四角形平面の煉瓦造煙突でイギリス積とし、頂部には鋸歯飾りを施す。別子鉱山における事業発展の歴史を示す地域のランドマーク。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007812"},{"id":"00005773","register_sub_id":"101","register_pk":"106761","name":"論田の西井出堰","kana":"ろんでんのにしいでぜき","category":"産業1次","subcategory":"土木構造物","type_guess":"水路・堰堤","type_guess_confidence":"low","period":"江戸","pref":"愛媛県","address":"愛媛県喜多郡内子町論田地先","lat":33.57548965,"lng":132.64896948,"geo_status":"db","era":"江戸後期／昭和前期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造、堤長30m、堤高3.3m","structure_material":"石造","registered":"2006.10.18(平成18.10.18)","register_no":"38 － 0071","desc":"高さ３．３ｍ，長さ３０ｍ規模で，岩盤面に敷いた松丸太の上に空石積で構築する。麓川の下流から上流に向けて，水田開発とともに築造された堰群の一つで，下流から７番目に位置し，地域の農耕の歴史を伝える遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005773"},{"id":"00004451","register_sub_id":"101","register_pk":"105441","name":"泉家住宅鰹節製造場","kana":"いずみけじゅうたくかつおぶしせいぞうじょう","category":"産業1次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和中","pref":"高知県","address":"高知県土佐市宇佐町宇佐1775-1","lat":33.45073467,"lng":133.44217809,"geo_status":"db","era":"昭和22頃","year":1947,"year_source":"db","year_min":1947,"year_max":1947,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積99㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0165","desc":"漁港に近い敷地南側に東西棟で建つ。桁行６間半梁間２間半規模，切妻造，桟瓦葺の木造平屋建で，東側を落棟とし，北面に１間半幅の土庇を差し掛けて作業場とする。内部は釜炊き場，燻し場，黴付け場，貯蔵場の４室から成る。鰹節製造の中心的施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004451"},{"id":"00004450","register_sub_id":"101","register_pk":"105440","name":"泉家住宅支度部屋及び干場","kana":"いずみけじゅうたくしたくべやおよびほしば","category":"産業1次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"高知県","address":"高知県土佐市宇佐町宇佐1775-1","lat":33.45078266,"lng":133.44219041,"geo_status":"db","era":"昭和22頃","year":1947,"year_source":"db","year_min":1947,"year_max":1947,"year_label":null,"structure":"木造2階及び平屋建、瓦葺、建築面積21㎡","structure_material":"木造2階及び平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0164","desc":"主屋２階西南に付属する支度部屋は桁行１間半梁間１間，南北棟，切妻造で，外部下見板張とし，階下は通用門とする。干場は桁行３間梁間１間半の南北棟，切妻造，桟瓦葺，平屋建で中庭側を吹き放ちとする。ともに昭和中期の鰹節の家内製造の様子を物語る施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004450"},{"id":"00001963","register_sub_id":"101","register_pk":"102953","name":"大西家住宅蔵","kana":"おおにしけじゅうたくくら","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県安芸郡奈半利町乙1728","lat":33.42507514,"lng":134.02295441,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積88㎡","structure_material":"土蔵造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0013","desc":"奈半利農協の前身が建設。桁行５間，梁行３間規模，切妻造，桟瓦葺，平入の２階建土蔵で，南面に奥行き１間半の下屋を差し出す。道路に面した西妻面は，腰を押縁下見とし，上部は鉄扉付窓の左右に水切瓦を振り分け，軒先は螻羽まで漆喰で塗込めた仕上とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001963"},{"id":"00000315","register_sub_id":"101","register_pk":"101305","name":"九州マクセル赤煉瓦記念館（旧三菱方城炭礦坑務工作室）","kana":"きゅうしゅうまくせるあかれんがきねんかん（きゅうみつびしほうじょうたんこうこうむこうさくしつ）","category":"産業1次","subcategory":"建築物","type_guess":"資料館","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県田川郡福智町伊方4680","lat":33.68257993,"lng":130.79217175,"geo_status":"db","era":"明治37頃","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"煉瓦造2階建塔屋付，スレート葺，建築面積297㎡","structure_material":"煉瓦造2階建塔屋付","registered":"1997.09.03(平成9.09.03)","register_no":"40 － 0003","desc":"明治３５年に開削に着手した方城炭礦の開発時の施設で，建設当初は扇風機室として利用された。煉瓦造，２階建で，通りに面した一部を３階建てとする。使用された煉瓦は炭礦開発のために特別に焼成したものと伝え，炭礦の往事の様子をよく示す施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000315"},{"id":"00000490","register_sub_id":"101","register_pk":"101480","name":"旧三池炭鉱宮浦坑煙突","kana":"きゅうみいけたんこうみやうらこうえんとつ","category":"産業1次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県大牟田市西宮浦町132-8","lat":33.02903526,"lng":130.45487388,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"煉瓦造煙突，高さ31.2m，基部直径4.3m","structure_material":"煉瓦造煙突","registered":"1998.01.16(平成10.01.16)","register_no":"40 － 0004","desc":"明治２０年に開削に着手した炭鉱に残る煉瓦造の円形煙突。蒸気動力のボイラーの排煙を目的に建設された。電化にともない多くの煙突が失われたため，三池炭鉱に現存する唯一の煙突となった。「炭鉱節」に唄われた三池炭鉱の煙突として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000490"},{"id":"00007323","register_sub_id":"101","register_pk":"108305","name":"旧三井寺ポンプ所及び変電所","kana":"きゅうみいでらぽんぷじょおよびへんでんしょ","category":"産業1次","subcategory":"建築物","type_guess":"発電・機械","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県久留米市三潴町高三潴字三井寺1101-7","lat":33.259071,"lng":130.458603,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積223㎡","structure_material":"煉瓦造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"40 － 0060","desc":"寄棟造の東棟と切妻造の南棟がＬ字型に続き、南棟の北に一段低い寄棟造の北棟が付く。イギリス積の煉瓦造平屋建で、屋根は桟瓦葺。面積２２３㎡。東棟と南棟には半円アーチ窓を開ける。小屋はキングポスト・トラス。田園風景の中に残る、もと農業用水施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007323"},{"id":"00000919","register_sub_id":"101","register_pk":"101909","name":"球磨地域農業協同組合第26号倉庫（山江倉庫２号）","kana":"くまちいきのうぎょうきょうどうくみあいだいにじゅうろくごうそうこ（やまえそうこにごう）","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県球磨郡山江村大字山田甲1416","lat":32.24925937,"lng":130.7684749,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"石造２階建，瓦葺，建築面積177㎡","structure_material":"石造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"43 － 0016","desc":"村の中心地に建つ石造２階建の農業用倉庫。正面には品質検査等を行うための吹き放しの庇が取り付く。比較的に規模が大きく，上階と下階で石材の厚さをかえるなどの工夫がみられるなど，地元産出の凝灰岩を利用した建物の模範的事例。軒廻りは近年の改造。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000919"},{"id":"00000552","register_sub_id":"101","register_pk":"101542","name":"郡築二番町樋門","kana":"ぐんちくにばんちょうひもん","category":"産業1次","subcategory":"土木構造物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県八代市郡築二番町字貮番割194-1地先","lat":32.52486641,"lng":130.5546961,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"石造アーチ式３連樋門，長さ14.2m，幅8.2m","structure_material":"石造アーチ式３連樋門","registered":"1998.04.21(平成10.04.21)","register_no":"43 － 0009","desc":"明治期に八代郡役所が干拓を行った事業地の堤防に設けられた樋門で，昭和11年の高潮被害後の補強改良工事時に設けられた。石造３連アーチからなり，上部は石造の布積みとし，曲線を用いた細部なども相まって，干拓事業の象徴として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000552"},{"id":"00007939","register_sub_id":"101","register_pk":"108919","name":"多良木町交流館石倉（旧多良木町農業会米倉庫）西棟","kana":"たらぎまちこうりゅうかんいしぐら（きゅうたらぎまちのうぎょうかいこめそうこ）にしとう","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県球磨郡多良木町大字多良木1542-1","lat":32.26217296,"lng":130.93311894,"geo_status":"db","era":"昭和10／平成17改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積166㎡","structure_material":"石造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"43-0109","desc":"東棟の西に５ｍほど離れて平行して建つ。東棟や南棟と同規模、同形式。内部はもとは一室。壁沿いに柱を建て、キングポストトラスとするが、トラスの端部は壁上部にも載せる。壁に沿って「荷摺り」と呼ばれる垂直材を建て、米俵が直接、壁に接しないようにする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007939"},{"id":"00007938","register_sub_id":"101","register_pk":"108918","name":"多良木町交流館石倉（旧多良木町農業会米倉庫）東棟","kana":"たらぎまちこうりゅうかんいしぐら（きゅうたらぎまちのうぎょうかいこめそうこ）ひがしとう","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県球磨郡多良木町大字多良木1542-1","lat":32.26224181,"lng":130.93327479,"geo_status":"db","era":"昭和10／平成17改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"石造平屋建、瓦葺 建築面積166㎡","structure_material":"石造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"43-0108","desc":"多良木駅の西南方に占める敷地の東寄りに同じ規模、形式の３棟が建つ。南北棟の切妻造桟瓦葺の石造平屋建。桁行１８ｍ梁間９．１ｍと大規模な石倉。地元産の薄い黄土色の溶結凝灰岩を切石積とする。壁厚は下部が３２㎝、上部が２６㎝で、構造的な安定を図る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007938"},{"id":"00007940","register_sub_id":"101","register_pk":"108920","name":"多良木町交流館石倉（旧多良木町農業会米倉庫）南棟","kana":"たらぎまちこうりゅうかんいしぐら（きゅうたらぎまちのうぎょうかいこめそうこ）みなみとう","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県球磨郡多良木町大字多良木1542-1","lat":32.26206995,"lng":130.93335057,"geo_status":"db","era":"昭和12／平成17改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積166㎡","structure_material":"石造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"43-0110","desc":"東棟の南に少し軸をずらせて南北棟として建つ。東棟や西棟と同規模、同形式の石倉。妻壁は中央上部中央に２ヵ所、平側は等間隔に３ヵ所、方形の小さな窓を開ける。多くの石倉が残る球磨地方において最大級の石倉であり、３棟が並び建つ姿は圧倒的存在感を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007940"},{"id":"00008223","register_sub_id":"101","register_pk":"132748","name":"旧高田農業倉庫北蔵","kana":"きゅうたかだのうぎょうそうこきたくら","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県豊後高田市新町字小塩田989-1","lat":33.55786326,"lng":131.43880465,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積640㎡","structure_material":"土蔵造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"44 － 0176","desc":"国東半島の米の収蔵施設として、駅に隣接する位置に建設された。南面して建つ、桁行４６ｍ梁間１１ｍの土蔵造平屋建で、南側の全面に奥行３．６ｍの下屋を張り出す。妻面には「高田農業倉庫」の鏝文字をあしらう。往時の繁栄を物語る大規模な米穀倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008223"},{"id":"00008224","register_sub_id":"101","register_pk":"132749","name":"旧高田農業倉庫北小蔵","kana":"きゅうたかだのうぎょうそうこきたこぐら","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県豊後高田市新町字花黒1009他","lat":33.55791753,"lng":131.43909055,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造平屋建、瓦葺、建築面積89㎡","structure_material":"土蔵造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"44 － 0177","desc":"北蔵の東北方に位置する。桁行１２ｍ梁間７．７ｍで、東面を半切妻造、西面を切妻造とする平屋建土蔵。外壁は白漆喰で仕上げ、壁の下端に金属板で開閉する円形通気口を設ける。北蔵や東蔵と同じ仕様をとりながら、小規模で屋根形式を違え、景観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008224"},{"id":"00008225","register_sub_id":"101","register_pk":"132750","name":"旧高田農業倉庫東蔵","kana":"きゅうたかだのうぎょうそうこひがしくら","category":"産業1次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県豊後高田市新町字花黒1009","lat":33.55772035,"lng":131.43913569,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造平屋建、瓦葺、建築面積626㎡","structure_material":"土蔵造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"44 － 0178","desc":"敷地東側に西面して建つ。桁行４０ｍ梁間１２ｍの土蔵平屋建、寄棟造、西側に奥行４．３ｍの下屋を張り出す。ほぼ正方形に区画された三室に対応して越屋根を三ヶ所設ける。小屋組はクイーンポストトラス。大規模な農業倉庫群であり、圧倒的な重量感を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008225"}];
